struct ServiceDetailsHttpResponse {
    status: u16,
    pair: Option<String>,
    body: Vec<u8>,
}

fn request_service_details(
    address: SocketAddr,
    route: &str,
) -> Result<ServiceDetailsHttpResponse, String> {
    request_service_details_with_etag(address, route, None)
}

fn request_service_details_with_etag(
    address: SocketAddr,
    route: &str,
    if_none_match: Option<&str>,
) -> Result<ServiceDetailsHttpResponse, String> {
    if let Some(pair) = if_none_match {
        if !valid_published_pair(pair) {
            return Err("invalid details generation header".into());
        }
    }
    let timeout = Duration::from_millis(500);
    let mut stream = TcpStream::connect_timeout(&address, timeout).map_err(|_| "connect failed")?;
    stream
        .set_read_timeout(Some(timeout))
        .map_err(|_| "read timeout setup failed")?;
    stream
        .set_write_timeout(Some(timeout))
        .map_err(|_| "write timeout setup failed")?;
    let conditional = if_none_match
        .map(|pair| format!("If-None-Match: \"{pair}\"\r\n"))
        .unwrap_or_default();
    let request = format!(
        "GET {route} HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\n{conditional}\r\n"
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "details request failed")?;
    let maximum = DETAILS_RESPONSE_MAX_BYTES + DETAILS_RESPONSE_HEADER_MAX_BYTES + 1;
    let mut response = Vec::new();
    stream
        .take(maximum as u64)
        .read_to_end(&mut response)
        .map_err(|_| "details response read failed")?;
    if response.len() >= maximum {
        return Err("details response exceeds bounded size".into());
    }
    let header_end = response
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .ok_or_else(|| "details response headers are incomplete".to_owned())?;
    if header_end + 4 > DETAILS_RESPONSE_HEADER_MAX_BYTES {
        return Err("details response headers are too large".into());
    }
    let header_bytes = &response[..header_end];
    if header_bytes.windows(2).any(|window| window == b"\n\n") {
        return Err("details response has invalid line endings".into());
    }
    let header_text =
        std::str::from_utf8(header_bytes).map_err(|_| "details response headers are not UTF-8")?;
    let mut lines = header_text.split("\r\n");
    let status_line = lines
        .next()
        .ok_or_else(|| "details response status is missing".to_owned())?;
    let mut status_fields = status_line.splitn(3, ' ');
    if status_fields.next() != Some("HTTP/1.1") {
        return Err("details response status is malformed".into());
    }
    let status = status_fields
        .next()
        .and_then(|value| value.parse::<u16>().ok())
        .ok_or_else(|| "details response status is malformed".to_owned())?;
    let mut pair = None;
    let mut content_length = None;
    let mut content_type = false;
    let mut cache_control = false;
    let mut connection_close = false;
    for line in lines {
        let (name, value) = line
            .split_once(": ")
            .ok_or_else(|| "details response header is malformed".to_owned())?;
        match name {
            "Codex-Info-Published-Pair" if pair.is_none() => pair = Some(value.to_owned()),
            "content-type" if !content_type && value == "application/json; charset=utf-8" => {
                content_type = true;
            }
            "cache-control" if !cache_control && value == "no-store" => {
                cache_control = true;
            }
            "content-length" if content_length.is_none() => {
                content_length = Some(
                    value
                        .parse::<usize>()
                        .map_err(|_| "invalid details content length")?,
                );
            }
            "connection" if !connection_close && value == "close" => connection_close = true,
            _ => return Err("unexpected or duplicate details response header".into()),
        }
    }
    if status == 200 || status == 304 {
        let pair_value = pair
            .as_deref()
            .ok_or_else(|| "missing details generation header".to_owned())?;
        if !valid_published_pair(pair_value) {
            return Err("details response generation header is invalid".into());
        }
    }
    if status != 200 && status != 304 && pair.is_some() {
        return Err("non-success details response has a generation header".into());
    }
    if !content_type || !cache_control || !connection_close {
        return Err("details response headers failed validation".into());
    }
    let body = &response[header_end + 4..];
    if body.len() > DETAILS_RESPONSE_MAX_BYTES || content_length != Some(body.len()) {
        return Err("details response body length mismatch".into());
    }
    if status == 304 && !body.is_empty() {
        return Err("not-modified details response has a body".into());
    }
    Ok(ServiceDetailsHttpResponse {
        status,
        pair,
        body: body.to_vec(),
    })
}

fn fetch_service_details(address: SocketAddr) -> Result<(String, PublicDetails), String> {
    let response = request_service_details(address, "/v1/details")?;
    if response.status != 200 {
        return Err("details response is not HTTP 200".into());
    }
    let pair = response
        .pair
        .ok_or_else(|| "missing details generation header".to_owned())?;
    Ok((pair, parse_details_document(&response.body)?))
}

fn fetch_service_details_v2(address: SocketAddr) -> Result<(String, PublicDetailsV2), String> {
    fetch_service_details_v2_with(|route| request_service_details(address, route))
}

fn fetch_service_details_v2_with<F>(mut request: F) -> Result<(String, PublicDetailsV2), String>
where
    F: FnMut(&str) -> Result<ServiceDetailsHttpResponse, String>,
{
    let response = request("/v2/details")?;
    if response.status == 404 {
        let fallback = request("/v1/details")?;
        if fallback.status != 200 {
            return Err("v1 details fallback response is not HTTP 200".into());
        }
        let pair = fallback
            .pair
            .ok_or_else(|| "missing details generation header".to_owned())?;
        let details = parse_details_document(&fallback.body)?;
        return Ok((pair, PublicDetailsV2::from(details)));
    }
    if response.status != 200 {
        return Err("v2 details response is not HTTP 200".into());
    }
    let pair = response
        .pair
        .ok_or_else(|| "missing details generation header".to_owned())?;
    Ok((pair, parse_details_v2_document(&response.body)?))
}

#[derive(Debug, PartialEq)]
enum ServiceDetailsV3Fetch {
    Fresh {
        pair: String,
        details: PublicDetailsV3,
        from_v3: bool,
    },
    NotModified {
        pair: String,
    },
}

fn response_published_pair(response: &ServiceDetailsHttpResponse) -> Result<String, String> {
    response
        .pair
        .clone()
        .ok_or_else(|| "missing details generation header".to_owned())
}

fn public_details_v3_from_v2(details: &PublicDetailsV2) -> PublicDetailsV3 {
    PublicDetailsV3 {
        state: details.state,
        observed_at: details.observed_at,
        authenticated: details.authenticated,
        plan_label: details.plan_label.clone(),
        quota: details.quota.clone(),
        models: details
            .models
            .iter()
            .map(|model| PublicModelUsageV3 {
                model: model.name.clone(),
                total_tokens: model
                    .input_tokens
                    .saturating_add(model.cached_input_tokens)
                    .saturating_add(model.output_tokens),
                input_tokens: model.input_tokens.saturating_add(model.cached_input_tokens),
                cached_input_tokens: model.cached_input_tokens,
                cache_write_input_tokens: None,
                output_tokens: model.output_tokens,
                estimated_cost: None,
            })
            .collect(),
        active_thread_count: details.active_thread_count,
        history_periods: details.history_periods.clone(),
        history_samples: details
            .history_samples
            .iter()
            .map(|sample| PublicHistoryObservationV3 {
                timestamp: sample.timestamp,
                reset_at: sample.reset_at,
                remaining_percent: sample.remaining_percent,
                models: legacy_history_models_v3(sample),
                models_complete: false,
                model_source: if sample.model_source == "unavailable" {
                    "unavailable".into()
                } else {
                    "legacy-unknown".into()
                },
            })
            .collect(),
        history_gaps: details.history_gaps.clone(),
        threads: details.threads.clone(),
    }
}

fn fetch_service_details_v3(
    address: SocketAddr,
    prior_pair: Option<&str>,
) -> Result<ServiceDetailsV3Fetch, String> {
    fetch_service_details_v3_with_etag(
        |route, if_none_match| {
            debug_runtime(format!(
                "requesting service details route={route} conditional={}",
                if_none_match.is_some()
            ));
            request_service_details_with_etag(address, route, if_none_match)
        },
        prior_pair,
    )
}

fn fetch_service_details_v3_with<F>(mut request: F) -> Result<(String, PublicDetailsV3), String>
where
    F: FnMut(&str) -> Result<ServiceDetailsHttpResponse, String>,
{
    let result = fetch_service_details_v3_with_etag(|route, _| request(route), None)?;
    match result {
        ServiceDetailsV3Fetch::Fresh { pair, details, .. } => Ok((pair, details)),
        ServiceDetailsV3Fetch::NotModified { .. } => {
            Err("unexpected not-modified details response".into())
        }
    }
}

fn fetch_service_details_v3_with_etag<F>(
    mut request: F,
    prior_pair: Option<&str>,
) -> Result<ServiceDetailsV3Fetch, String>
where
    F: FnMut(&str, Option<&str>) -> Result<ServiceDetailsHttpResponse, String>,
{
    if let Some(pair) = prior_pair {
        if !valid_published_pair(pair) {
            return Err("invalid details generation header".into());
        }
    }
    let response = request("/v3/details", prior_pair)?;
    if response.status == 304 {
        let pair = response_published_pair(&response)?;
        if prior_pair != Some(pair.as_str()) || !response.body.is_empty() {
            return Err("not-modified details response does not match last v3 root".into());
        }
        return Ok(ServiceDetailsV3Fetch::NotModified { pair });
    }
    if response.status == 404 {
        let legacy_v2 = request("/v2/details", None)?;
        if legacy_v2.status == 404 {
            let legacy_v1 = request("/v1/details", None)?;
            if legacy_v1.status != 200 {
                return Err("v1 details fallback response is not HTTP 200".into());
            }
            let pair = response_published_pair(&legacy_v1)?;
            let details = parse_details_document(&legacy_v1.body)?;
            let details = public_details_v3_from_v2(&PublicDetailsV2::from(details));
            return Ok(ServiceDetailsV3Fetch::Fresh {
                pair,
                details,
                from_v3: false,
            });
        }
        if legacy_v2.status != 200 {
            return Err("v2 details fallback response is not HTTP 200".into());
        }
        let pair = response_published_pair(&legacy_v2)?;
        let details = parse_details_v2_document(&legacy_v2.body)?;
        return Ok(ServiceDetailsV3Fetch::Fresh {
            pair,
            details: public_details_v3_from_v2(&details),
            from_v3: false,
        });
    }
    if response.status != 200 {
        return Err("v3 details response is not HTTP 200".into());
    }
    let pair = response_published_pair(&response)?;
    let details = parse_details_v3_document(&response.body)?;
    Ok(ServiceDetailsV3Fetch::Fresh {
        pair,
        details,
        from_v3: true,
    })
}

fn cli_error(key: CliTextKey) -> String {
    I18n::detect().cli_text(key).to_owned()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum LaunchMode {
    /// Mode 1: one resident owner containing recorder + REST.
    Service(ApiServerConfig),
    /// Mode 2: ensure a resident service exists at this address, then add X UI.
    All(ApiServerConfig),
    /// Stop this profile's verified resident service and wait for its lock to disappear.
    Stop,
    /// Print CLI usage without starting a daemon or UI.
    Help,
}

fn default_service_config() -> Result<ApiServerConfig, String> {
    DEFAULT_SERVICE_ADDRESS
        .parse::<SocketAddr>()
        .map_err(|_| cli_error(CliTextKey::ServiceStartFailed))
        .and_then(|address| {
            ApiServerConfig::new(address).map_err(|_| cli_error(CliTextKey::ServiceStartFailed))
        })
}

fn service_config_for_port(value: &std::ffi::OsStr) -> Result<ApiServerConfig, String> {
    let port = value
        .to_str()
        .ok_or_else(|| cli_error(CliTextKey::InvalidPort))?
        .parse::<u16>()
        .map_err(|_| cli_error(CliTextKey::InvalidPort))?;
    if port == 0 {
        return Err(cli_error(CliTextKey::InvalidPort));
    }
    ApiServerConfig::new(SocketAddr::from(([127, 0, 0, 1], port)))
        .map_err(|_| cli_error(CliTextKey::ServiceStartFailed))
}

fn parse_launch_mode<I>(arguments: I) -> Result<LaunchMode, String>
where
    I: IntoIterator<Item = OsString>,
{
    let arguments = arguments.into_iter().collect::<Vec<_>>();
    match arguments.as_slice() {
        [] => default_service_config().map(LaunchMode::Service),
        [value] if value == "--help" || value == "--h" || value == "-h" => Ok(LaunchMode::Help),
        [value] if value == "--ui" => default_service_config().map(LaunchMode::All),
        [stop] if stop == "--stop" => Ok(LaunchMode::Stop),
        [port, value] if port == "--port" => {
            service_config_for_port(value).map(LaunchMode::Service)
        }
        [ui, port, value] if ui == "--ui" && port == "--port" => {
            service_config_for_port(value).map(LaunchMode::All)
        }
        _ => Err(I18n::detect().language().launch_help().to_owned()),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ServiceHealthVersion {
    Current,
    Different,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ServiceEndpointState {
    Absent,
    Current,
    Different,
    Unrecognized,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct VersionedServiceHealth {
    api_version: String,
    service: String,
    product_version: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct LegacyServiceHealth {
    api_version: String,
    service: String,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum ServiceHealthDocument {
    Versioned(VersionedServiceHealth),
    Legacy(LegacyServiceHealth),
}

fn is_stable_product_version(value: &str) -> bool {
    let mut components = value.split('.');
    let valid_component = |component: &str| {
        !component.is_empty()
            && (component == "0" || !component.starts_with('0'))
            && component.bytes().all(|byte| byte.is_ascii_digit())
    };
    components.next().is_some_and(valid_component)
        && components.next().is_some_and(valid_component)
        && components.next().is_some_and(valid_component)
        && components.next().is_none()
}

fn service_health_response_version(response: &[u8]) -> Option<ServiceHealthVersion> {
    if !response.starts_with(b"HTTP/1.1 200 ") {
        return None;
    }
    let header_end = response
        .windows(4)
        .position(|window| window == b"\r\n\r\n")?;
    let body = &response[header_end + 4..];
    match serde_json::from_slice::<ServiceHealthDocument>(body).ok()? {
        // Keep the legacy two-key classification for the launcher owner
        // retirement path. `service_is_healthy` below still requires the
        // versioned schema before a UI treats the endpoint as ready.
        ServiceHealthDocument::Legacy(document)
            if document.api_version == "v1" && document.service == "codex-info" =>
        {
            Some(ServiceHealthVersion::Different)
        }
        ServiceHealthDocument::Versioned(document)
            if document.api_version == "v1"
                && document.service == "codex-info"
                && is_stable_product_version(&document.product_version) =>
        {
            Some(if document.product_version == PRODUCT_VERSION {
                ServiceHealthVersion::Current
            } else {
                ServiceHealthVersion::Different
            })
        }
        _ => None,
    }
}

#[cfg(test)]
fn is_service_health_response(response: &[u8]) -> bool {
    service_health_response_version(response) == Some(ServiceHealthVersion::Current)
}

fn service_endpoint_state(address: SocketAddr) -> ServiceEndpointState {
    let timeout = Duration::from_millis(150);
    let Ok(mut stream) = TcpStream::connect_timeout(&address, timeout) else {
        return ServiceEndpointState::Absent;
    };
    let request =
        format!("GET /v1/health HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\n\r\n");
    if stream.set_read_timeout(Some(timeout)).is_err()
        || stream.set_write_timeout(Some(timeout)).is_err()
        || stream.write_all(request.as_bytes()).is_err()
    {
        return ServiceEndpointState::Unrecognized;
    }
    let mut response = Vec::with_capacity(512);
    let mut buffer = [0_u8; 512];
    while response.len() < 4096 {
        let remaining = 4096 - response.len();
        let read_limit = remaining.min(buffer.len());
        match stream.read(&mut buffer[..read_limit]) {
            Ok(0) => break,
            Ok(read) => {
                response.extend_from_slice(&buffer[..read]);
                // The server supplies Content-Length and may keep the socket
                // open. A complete, validated body is success; EOF is not a
                // health requirement.
                if let Some(version) = service_health_response_version(&response) {
                    return match version {
                        ServiceHealthVersion::Current => ServiceEndpointState::Current,
                        ServiceHealthVersion::Different => ServiceEndpointState::Different,
                    };
                }
            }
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                break;
            }
            Err(_) => return ServiceEndpointState::Unrecognized,
        }
    }
    match service_health_response_version(&response) {
        Some(ServiceHealthVersion::Current) => ServiceEndpointState::Current,
        Some(ServiceHealthVersion::Different) => ServiceEndpointState::Different,
        None => ServiceEndpointState::Unrecognized,
    }
}

fn service_health_version(address: SocketAddr) -> Option<ServiceHealthVersion> {
    match service_endpoint_state(address) {
        ServiceEndpointState::Current => Some(ServiceHealthVersion::Current),
        ServiceEndpointState::Different => Some(ServiceHealthVersion::Different),
        ServiceEndpointState::Absent | ServiceEndpointState::Unrecognized => None,
    }
}

fn service_is_healthy(address: SocketAddr) -> bool {
    let timeout = Duration::from_millis(150);
    let Ok(mut stream) = TcpStream::connect_timeout(&address, timeout) else {
        return false;
    };
    let request =
        format!("GET /v1/health HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\n\r\n");
    if stream.set_read_timeout(Some(timeout)).is_err()
        || stream.set_write_timeout(Some(timeout)).is_err()
        || stream.write_all(request.as_bytes()).is_err()
    {
        return false;
    }
    let mut response = Vec::with_capacity(512);
    let mut buffer = [0_u8; 512];
    while response.len() < 4096 {
        let remaining = 4096 - response.len();
        let read_limit = remaining.min(buffer.len());
        match stream.read(&mut buffer[..read_limit]) {
            Ok(0) => break,
            Ok(read) => response.extend_from_slice(&buffer[..read]),
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                break
            }
            Err(_) => return false,
        }
    }
    let Some(header_end) = response.windows(4).position(|window| window == b"\r\n\r\n") else {
        return false;
    };
    if !response.starts_with(b"HTTP/1.1 200 ") {
        return false;
    }
    let Ok(document) =
        serde_json::from_slice::<VersionedServiceHealth>(&response[header_end + 4..])
    else {
        // A missing product_version is not a schema-valid readiness signal.
        return false;
    };
    document.api_version == "v1"
        && document.service == "codex-info"
        && is_stable_product_version(&document.product_version)
}

fn recorder_owner_is_healthy(owner: &daemon::DaemonOwnerIdentity) -> bool {
    let Ok(Some(state)) = daemon::read_recorder_state() else {
        return false;
    };
    let now = Utc::now().timestamp().max(1);
    if state.pid != owner.pid
        || state.process_starttime != owner.starttime_ticks
        || state.owner_nonce != owner.owner_nonce
        || state.updated_at_unix > now
        || now.saturating_sub(state.updated_at_unix) > daemon::RECORDER_LAST_COMMIT_MAX_AGE_SECS
    {
        return false;
    }
    match state.write_state {
        daemon::RecorderWriteState::IdleNoAccount => true,
        daemon::RecorderWriteState::Ready => state.last_commit_unix.is_some_and(|last_commit| {
            now.saturating_sub(last_commit) <= daemon::RECORDER_LAST_COMMIT_MAX_AGE_SECS
        }),
        daemon::RecorderWriteState::Degraded => false,
    }
}

fn healthy_combined_service_owner(address: SocketAddr) -> Option<u32> {
    if !service_is_healthy(address) {
        return None;
    }
    // A healthy HTTP document is not an owner credential.  Only a current
    // lock whose process is an explicitly managed service or an exact known
    // Codex invocation may be paired with the endpoint; a foreign/malformed
    // owner must never be adopted by UI attachment or startup races.
    if !matches!(
        daemon::classify_profile_owner(),
        daemon::OwnerClassification::ManagedActive
            | daemon::OwnerClassification::KnownUnmanagedCodex
    ) {
        return None;
    }
    let owner = daemon::current_daemon_owner_identity()?;
    if !recorder_owner_is_healthy(&owner) {
        return None;
    }
    // Re-read the endpoint after the lock snapshot.  A stale HTTP 200 from a
    // listener that is closing must never be paired with a newer/different
    // profile owner during UI attachment or concurrent startup.
    (service_is_healthy(address)
        && daemon::current_daemon_owner_identity().is_some_and(|current| current == owner))
    .then_some(owner.pid)
}

fn systemd_managed_activation() -> bool {
    std::env::var_os("CODEX_INFO_SYSTEMD_MANAGED").is_some_and(|value| value == "1")
}

/// The installed launcher sets this marker only for its verified fallback
/// path after a service-start failure.  That path is a UI client, never a
/// second resident owner: malformed marker values fail closed instead of
/// silently falling back to the direct-development `--ui` contract.
fn ui_client_only_marker_value(value: Option<&std::ffi::OsStr>) -> Result<bool, String> {
    match value {
        None => Ok(false),
        Some(value) if value == "1" => Ok(true),
        Some(_) => Err(cli_error(CliTextKey::ServiceStateUnavailable)),
    }
}

fn ui_client_only_mode() -> Result<bool, String> {
    ui_client_only_marker_value(std::env::var_os("CODEX_INFO_UI_CLIENT_ONLY").as_deref())
}

/// Reconcile the profile owner before a systemd-managed service binds its
/// listener.  A managed activation may retire only an exact, known Codex
/// owner validated by the existing lock/PID/starttime/executable identity
/// contract.  An owner with an unknown executable, malformed lock, or no lock
/// is never guessed at or killed, even when the port happens to look healthy.
fn reconcile_managed_service_owner(address: SocketAddr) -> Result<bool, String> {
    let deadline = Instant::now() + BACKGROUND_SERVICE_START_TIMEOUT;
    loop {
        let endpoint = service_endpoint_state(address);
        match daemon::classify_profile_owner() {
            daemon::OwnerClassification::ManagedActive
                if endpoint == ServiceEndpointState::Current =>
            {
                if let Some(owner) = daemon::current_daemon_owner_identity() {
                    if recorder_owner_is_healthy(&owner) {
                        return Ok(true);
                    }
                }
                // The marker identifies a managed process, but stale/missing
                // recorder state is not health. Retire only this exact owner
                // and establish a fresh state/listener below.
                daemon::stop_daemon().map_err(|error| {
                    format!("managed service could not retire unhealthy owner: {error:?}")
                })?;
            }
            daemon::OwnerClassification::ManagedActive
            | daemon::OwnerClassification::KnownUnmanagedCodex => {
                daemon::stop_daemon().map_err(|error| {
                    format!("managed service could not retire verified owner: {error:?}")
                })?;
            }
            daemon::OwnerClassification::Stale => {
                // The lock acquisition path will reclaim a dead/stale lock
                // using the same inode race check.  A listener that survives
                // without a valid owner remains an unknown occupant.
                if endpoint == ServiceEndpointState::Absent {
                    return Ok(false);
                }
                // A dead owner can leave its socket in the process of closing;
                // wait for that listener instead of adopting an old HTTP 200.
            }
            daemon::OwnerClassification::NoOwner => {
                if endpoint == ServiceEndpointState::Absent {
                    return Ok(false);
                }
                // The verified owner has just released its lock.  Its socket
                // may close slightly later, so keep waiting without assigning
                // authority to the lockless listener.
            }
            daemon::OwnerClassification::Malformed | daemon::OwnerClassification::Foreign => {
                return Err(cli_error(CliTextKey::ServiceStateUnavailable));
            }
        }

        // stop_daemon waits for lock release, but the old listener may close
        // a few milliseconds later.  Keep the decision bounded and do not
        // treat an old HTTP 200 as permission to attach to an unknown owner.
        if Instant::now() >= deadline {
            return Err(cli_error(CliTextKey::ServiceCleanupFailed));
        }
        thread::sleep(Duration::from_millis(25));
    }
}

fn retire_different_version_service(address: SocketAddr) -> Result<(), String> {
    if service_endpoint_state(address) != ServiceEndpointState::Different {
        return Ok(());
    }
    if !matches!(
        daemon::classify_profile_owner(),
        daemon::OwnerClassification::ManagedActive
            | daemon::OwnerClassification::KnownUnmanagedCodex
    ) {
        // A different-version response without an exact known Codex owner is
        // still an unknown occupant. Never send the public stop signal based
        // on HTTP health or a bare PID.
        return Err(cli_error(CliTextKey::ServiceStateUnavailable));
    }
    daemon::stop_daemon().map_err(|error| format!("verified service stop failed: {error:?}"))?;
    // The legacy process releases its recorder lock immediately before closing
    // the REST listener. A malformed/incomplete response still means that the
    // port is occupied, so wait for an actually absent listener or a concurrent
    // current-version winner before the one-shot start decision below.
    let deadline = Instant::now() + BACKGROUND_SERVICE_START_TIMEOUT;
    loop {
        match service_endpoint_state(address) {
            ServiceEndpointState::Absent | ServiceEndpointState::Current => return Ok(()),
            ServiceEndpointState::Different | ServiceEndpointState::Unrecognized => {}
        }
        if Instant::now() >= deadline {
            return Err(cli_error(CliTextKey::ServiceCleanupFailed));
        }
        thread::sleep(Duration::from_millis(25));
    }
}

fn terminate_and_reap_owned_child(child: &mut Child) -> bool {
    if matches!(child.try_wait(), Ok(Some(_))) {
        return true;
    }
    // The child is ours, but still pin its process instance before requesting
    // termination. A forceful Child::kill would bypass the pidfd contract used
    // by the public --stop path.
    if !daemon::send_term_to_owned_process(child.id()) {
        return false;
    }
    let deadline = Instant::now() + BACKGROUND_CHILD_CLEANUP_TIMEOUT;
    loop {
        if matches!(child.try_wait(), Ok(Some(_))) {
            return true;
        }
        if Instant::now() >= deadline {
            return false;
        }
        thread::sleep(Duration::from_millis(10));
    }
}

fn ensure_background_service(config: ApiServerConfig) -> Result<(), String> {
    let address = config.listen_addr();
    if healthy_combined_service_owner(address).is_some() {
        return Ok(());
    }
    retire_different_version_service(address)?;
    let executable =
        std::env::current_exe().map_err(|_| cli_error(CliTextKey::ServiceExecutableUnavailable))?;
    let port_text = address.port().to_string();
    let child = Command::new(executable)
        .args(["--port", port_text.as_str()])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .map_err(|_| cli_error(CliTextKey::ServiceStartFailed))?;
    let child_pid = child.id();
    let mut owned_child = Some(child);
    let deadline = Instant::now() + BACKGROUND_SERVICE_START_TIMEOUT;
    loop {
        let healthy_owner = healthy_combined_service_owner(address);
        if healthy_owner == Some(child_pid) {
            // This is the resident child this UI+service invocation intentionally
            // created. Dropping the process handle detaches it; it must remain
            // alive after the X UI closes.
            return Ok(());
        }
        if healthy_owner.is_some() {
            // A concurrent UI/service launcher won recorder ownership and became
            // healthy. This invocation must reap only the child it spawned
            // before attaching its UI to that winner.
            if let Some(child) = owned_child.as_mut() {
                if !terminate_and_reap_owned_child(child) {
                    return Err(cli_error(CliTextKey::ServiceCleanupFailed));
                }
            }
            return Ok(());
        }

        if let Some(child) = owned_child.as_mut() {
            match child.try_wait() {
                Ok(Some(_)) => owned_child = None,
                Ok(None) => {}
                Err(_) => {
                    let reaped = terminate_and_reap_owned_child(child);
                    return Err(if reaped {
                        cli_error(CliTextKey::ServiceStateUnavailable)
                    } else {
                        cli_error(CliTextKey::ServiceCleanupFailed)
                    });
                }
            }
        }
        if owned_child.is_none() && daemon::current_daemon_owner_pid().is_none() {
            return Err(cli_error(CliTextKey::ServiceExitedBeforeHealthy));
        }
        if Instant::now() >= deadline {
            let reaped = owned_child
                .as_mut()
                .is_none_or(terminate_and_reap_owned_child);
            return Err(if reaped {
                cli_error(CliTextKey::ServiceNotHealthy)
            } else {
                cli_error(CliTextKey::ServiceCleanupFailed)
            });
        }
        thread::sleep(Duration::from_millis(50));
    }
}

fn start_background_service_retry<F>(
    state: &mut CodexInfoState,
    config: ApiServerConfig,
    in_flight: &Arc<AtomicBool>,
    start_service: F,
) -> bool
where
    F: FnOnce(ApiServerConfig) -> Result<(), String> + Send + 'static,
{
    if state.service_endpoint_error.is_none()
        || in_flight
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
    {
        return false;
    }
    state.request_service_read("利用状況を更新しています…");
    let worker_in_flight = Arc::clone(in_flight);
    if thread::Builder::new()
        .spawn(move || {
            let _ = start_service(config);
            worker_in_flight.store(false, Ordering::Release);
        })
        .is_err()
    {
        in_flight.store(false, Ordering::Release);
        state.hold_service_endpoint_error(cli_error(CliTextKey::ServiceStartFailed));
        return false;
    }
    true
}

fn poll_service_state_with_owner_check<F>(
    state: &mut CodexInfoState,
    service_endpoint: SocketAddr,
    owner_is_healthy: F,
) where
    F: FnOnce(SocketAddr) -> bool,
{
    state.poll_auth_control();
    // Endpoint health alone is not an owner identity.  Pair the strict health
    // document with two lock snapshots so a closing old listener cannot feed
    // stale data into the UI while a different service is taking ownership.
    if !owner_is_healthy(service_endpoint) {
        debug_runtime("service owner validation failed");
        let error = state
            .service_endpoint_error
            .clone()
            .unwrap_or_else(|| cli_error(CliTextKey::ServiceStateUnavailable));
        state.hold_service_endpoint_error(error);
        return;
    }
    let previous_v3_pair = state.service_v3_published_pair.clone();
    let fetched = fetch_service_details_v3_with_etag(
        |route, if_none_match| {
            if route == "/v3/details" {
                request_service_details_with_etag(service_endpoint, route, if_none_match)
            } else {
                // Fallback requests intentionally omit If-None-Match so an
                // older daemon receives the exact legacy request shape.
                request_service_details(service_endpoint, route)
            }
        },
        previous_v3_pair.as_deref(),
    );
    let result = fetched.and_then(|result| match result {
        ServiceDetailsV3Fetch::Fresh {
            pair,
            details,
            from_v3,
        } => {
            if !from_v3 {
                state.service_v3_published_pair = None;
            }
            state.apply_service_details_v3(pair, details)
        }
        ServiceDetailsV3Fetch::NotModified { pair } => {
            if state.service_v3_published_pair.as_deref() != Some(pair.as_str()) {
                return Err("not-modified details response does not match last v3 root".into());
            }
            Ok(false)
        }
    });
    match result {
        Ok(_) => {
            // A complete strict read proves that the selected endpoint has
            // recovered even when its immutable generation is unchanged.
            state.service_endpoint_error = None;
            state.last_poll = Instant::now();
        }
        Err(error) => {
            debug_runtime(format!("service details read failed: {error}"));
            state.hold_service_endpoint_error(error);
        }
    }
}

fn poll_service_state(state: &mut CodexInfoState, service_endpoint: SocketAddr) {
    poll_service_state_with_owner_check(state, service_endpoint, |address| {
        healthy_combined_service_owner(address).is_some()
    });
}

fn run_ui_service_timer_cycle(state: &mut CodexInfoState, service_endpoint: SocketAddr) {
    poll_service_state(state, service_endpoint);
}

async fn service_shutdown_signal() {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal, SignalKind};
        let ctrl_c = tokio::signal::ctrl_c();
        if let Ok(mut terminate) = signal(SignalKind::terminate()) {
            tokio::select! {
                _ = ctrl_c => {}
                _ = terminate.recv() => {}
            }
        } else {
            let _ = ctrl_c.await;
        }
    }
    #[cfg(not(unix))]
    {
        let _ = tokio::signal::ctrl_c().await;
    }
}

#[derive(Debug)]
enum ResidentServiceCycleError {
    Store(String),
    Candidate(String),
    Publish(codex_info::server::ApiSnapshotError),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ResidentServiceCycleOutcome {
    Published,
    HeldIncomplete,
}

fn recorder_attempt_due(now: Instant, retry_at: Option<Instant>) -> bool {
    retry_at.is_none_or(|retry_at| now >= retry_at)
}

fn pending_gap_for_shutdown(
    state: &CodexInfoState,
    active_partition: Option<&str>,
) -> Option<usage_store::RecorderGap> {
    let active_partition = active_partition?;
    let partition = state.account_partition.as_ref()?;
    if partition.partition_id != active_partition {
        return None;
    }
    let now = Utc::now().timestamp().max(1);
    let acknowledged = state
        .acknowledged_recorder_commit
        .as_ref()
        .filter(|commit| commit.partition_id == active_partition);
    let start_at = acknowledged
        .map(|commit| commit.last_commit_unix)
        .filter(|timestamp| *timestamp > 0 && *timestamp <= now)
        .unwrap_or(now);
    let owner_collector_epoch = acknowledged
        .map(|commit| commit.collector_epoch)
        .filter(|epoch| *epoch > 0)
        .unwrap_or(1);
    let confirmation_cycle_seq = acknowledged
        .map(|commit| commit.cycle_seq)
        .filter(|cycle| *cycle > 0)
        .unwrap_or(1);
    let cursor = acknowledged
        .map(|commit| format!("generation-{}", commit.data_generation))
        .unwrap_or_else(|| "generation-0".into());
    let stopped_at_monotonic_ns = daemon::monotonic_now_ns();
    if stopped_at_monotonic_ns == 0 {
        return None;
    }
    let mut digest = Sha256::new();
    digest.update(active_partition.as_bytes());
    digest.update(stopped_at_monotonic_ns.to_be_bytes());
    digest.update(std::process::id().to_be_bytes());
    let digest = digest.finalize();
    let gap_id = digest[..16]
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    Some(usage_store::RecorderGap {
        gap_id,
        partition_id: active_partition.to_owned(),
        source_identity_before: format!("resident:{active_partition}"),
        source_identity_after: "unresolved".into(),
        cursor_before: cursor,
        cursor_after: "unresolved".into(),
        stopped_at_monotonic_ns,
        resumed_at_monotonic_ns: None,
        start_at,
        end_at: now,
        reset_at: state.reset_at.filter(|reset| *reset > 0),
        reason: "daemon_stop_unrecoverable".into(),
        state: "pending".into(),
        owner_collector_epoch,
        confirmation_cycle_seq,
    })
}

#[derive(Default)]
struct ResidentPublicationState {
    /// Exact last complete root accepted by the REST publisher. This is the
    /// publication buffer, not another collector: failures may change only
    /// its state marker while every displayed data field remains identical.
    last_complete: Option<PublicDetails>,
    last_complete_v2: Option<PublicDetailsV2>,
    last_complete_v3: Option<PublicDetailsV3>,
}

#[cfg(test)]
fn resident_service_cycle<W, P>(
    state: &mut CodexInfoState,
    publication: &mut ResidentPublicationState,
    write_and_refresh: W,
    publish: P,
) -> Result<ResidentServiceCycleOutcome, ResidentServiceCycleError>
where
    W: FnOnce(&mut CodexInfoState, PendingRecorderBatch) -> Result<(), String>,
    P: FnOnce(PublicDetails) -> Result<(), codex_info::server::ApiSnapshotError>,
{
    resident_service_cycle_with_recorder_attempt(
        state,
        publication,
        true,
        write_and_refresh,
        publish,
    )
}

fn resident_service_cycle_with_recorder_attempt<W, P>(
    state: &mut CodexInfoState,
    publication: &mut ResidentPublicationState,
    recorder_attempt: bool,
    write_and_refresh: W,
    publish: P,
) -> Result<ResidentServiceCycleOutcome, ResidentServiceCycleError>
where
    W: FnOnce(&mut CodexInfoState, PendingRecorderBatch) -> Result<(), String>,
    P: FnOnce(PublicDetails) -> Result<(), codex_info::server::ApiSnapshotError>,
{
    resident_service_cycle_with_recorder_attempt_v2(
        state,
        publication,
        recorder_attempt,
        write_and_refresh,
        |candidate, _candidate_v2| publish(candidate),
    )
}

fn resident_service_cycle_with_recorder_attempt_v2<W, P>(
    state: &mut CodexInfoState,
    publication: &mut ResidentPublicationState,
    recorder_attempt: bool,
    write_and_refresh: W,
    publish: P,
) -> Result<ResidentServiceCycleOutcome, ResidentServiceCycleError>
where
    W: FnOnce(&mut CodexInfoState, PendingRecorderBatch) -> Result<(), String>,
    P: FnOnce(PublicDetails, PublicDetailsV2) -> Result<(), codex_info::server::ApiSnapshotError>,
{
    resident_service_cycle_with_recorder_attempt_v3(
        state,
        publication,
        recorder_attempt,
        write_and_refresh,
        |v1, v2, _v3| publish(v1, v2),
    )
}

fn resident_service_cycle_with_recorder_attempt_v3<W, P>(
    state: &mut CodexInfoState,
    publication: &mut ResidentPublicationState,
    recorder_attempt: bool,
    write_and_refresh: W,
    publish: P,
) -> Result<ResidentServiceCycleOutcome, ResidentServiceCycleError>
where
    W: FnOnce(&mut CodexInfoState, PendingRecorderBatch) -> Result<(), String>,
    P: FnOnce(
        PublicDetails,
        PublicDetailsV2,
        PublicDetailsV3,
    ) -> Result<(), codex_info::server::ApiSnapshotError>,
{
    state.poll();
    // Logout/account replacement is the only event that invalidates the old
    // visible root. An incomplete first generation must never inherit a
    // previous identity's data.
    if !state.usage_snapshot_committed {
        publication.last_complete = None;
        publication.last_complete_v2 = None;
        publication.last_complete_v3 = None;
    }
    state.schedule_resident_refresh(Instant::now());
    let store_error = if recorder_attempt {
        let pending = state.take_pending_recorder_batch();
        match write_and_refresh(state, pending.clone()) {
            Ok(()) => {
                state.clear_recorder_store_error();
                None
            }
            Err(error) => {
                state.restore_pending_recorder_batch(pending);
                state.apply_recorder_store_error();
                Some(error)
            }
        }
    } else {
        // A failed store keeps its exact batch in state.  During the bounded
        // retry interval publish only the latched error/last-good root; never
        // consume the batch merely to skip an attempt.
        None
    };
    // A storage/identity failure can be discovered by the writer callback
    // after the pre-write publication check. Re-apply the hard boundary here
    // so last-good data from another/unverified partition is never merged
    // back into the error document.
    if !state.usage_snapshot_committed {
        publication.last_complete = None;
        publication.last_complete_v2 = None;
        publication.last_complete_v3 = None;
    }
    // A quota response is only the first half of a public generation. Keep
    // the publisher's exact root and generation identity unchanged until the
    // matching local usage/history result reaches a terminal state.
    if state.local_usage_pending && state.account_error.is_none() {
        return Ok(ResidentServiceCycleOutcome::HeldIncomplete);
    }
    let mut candidate = state
        .public_details_candidate()
        .map_err(|error| ResidentServiceCycleError::Candidate(error.to_string()))?;
    let mut candidate_v2 = state
        .public_details_v2_candidate()
        .map_err(|error| ResidentServiceCycleError::Candidate(error.to_string()))?;
    let mut candidate_v3 = state
        .public_details_v3_candidate()
        .map_err(|error| ResidentServiceCycleError::Candidate(error.to_string()))?;
    if candidate.state == PublicState::Error {
        if let Some(last_complete) = publication.last_complete.as_ref() {
            candidate = last_complete.clone();
            candidate.state = PublicState::Error;
            if let Some(last_complete_v2) = publication.last_complete_v2.as_ref() {
                candidate_v2 = last_complete_v2.clone();
                candidate_v2.state = PublicState::Error;
            }
            if let Some(last_complete_v3) = publication.last_complete_v3.as_ref() {
                candidate_v3 = last_complete_v3.clone();
                candidate_v3.state = PublicState::Error;
            }
        } else if store_error.is_some() {
            // The collector result has not become durable and therefore is
            // not a publishable first snapshot. Keep identity/plan context,
            // but expose no usage payload until the pending batch commits.
            candidate.observed_at = None;
            candidate.quota = None;
            candidate.models.clear();
            candidate.active_thread_count = 0;
            candidate.history_periods.clear();
            candidate.history_samples.clear();
            candidate.history_gaps.clear();
            candidate.threads.clear();
            candidate_v2 = PublicDetailsV2::from(candidate.clone());
            candidate_v3 = PublicDetailsV3::default();
            candidate_v3.state = PublicState::Error;
            candidate_v3.authenticated = candidate.authenticated;
            candidate_v3.plan_label = candidate.plan_label.clone();
        }
    }
    publish(
        candidate.clone(),
        candidate_v2.clone(),
        candidate_v3.clone(),
    )
    .map_err(ResidentServiceCycleError::Publish)?;
    if candidate.state == PublicState::Ready {
        publication.last_complete = Some(candidate);
        publication.last_complete_v2 = Some(candidate_v2);
        publication.last_complete_v3 = Some(candidate_v3);
    } else if !candidate.authenticated {
        publication.last_complete = None;
        publication.last_complete_v2 = None;
        publication.last_complete_v3 = None;
    }
    if let Some(error) = store_error {
        Err(ResidentServiceCycleError::Store(error))
    } else {
        Ok(ResidentServiceCycleOutcome::Published)
    }
}

fn run_combined_service(config: ApiServerConfig) -> Result<(), Box<dyn std::error::Error>> {
    let mut recorder = daemon::RecorderWorker::start()
        .map_err(|_| std::io::Error::other(cli_error(CliTextKey::ServiceStartFailed)))?;
    if !recorder.is_active() {
        recorder.shutdown();
        return Err(std::io::Error::other(cli_error(CliTextKey::ServiceAlreadyOwned)).into());
    }
    // Bind REST only after this process owns the recorder. Concurrent service
    // children therefore exit before publishing a listener, and an API bind
    // failure drops the worker and releases its exact lock identity.
    let mut api_server = ApiServer::start(config)
        .map_err(|_| std::io::Error::other(cli_error(CliTextKey::ServiceStartFailed)))?;
    let publisher = api_server.publisher();
    let mut state = CodexInfoState::new();
    publisher.publish_details_v3(
        state.public_details_candidate()?,
        state.public_details_v2_candidate()?,
        state.public_details_v3_candidate()?,
    )?;
    let mut publication = ResidentPublicationState::default();
    let mut last_recorder_error = None;
    let mut last_publish_error = None;
    let mut active_recorder_partition: Option<String> = None;
    eprintln!(
        "codex-info: daemon+REST listening on {} recorder_owner={}",
        api_server.local_addr(),
        recorder.is_active()
    );

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_io()
        .enable_time()
        .build()?;
    let runtime_result = runtime.block_on(async {
        let mut ticker = tokio::time::interval(Duration::from_secs(1));
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        let shutdown = service_shutdown_signal();
        tokio::pin!(shutdown);
        let mut recorder_retry_at: Option<Instant> = None;
        loop {
            tokio::select! {
                _ = &mut shutdown => return Ok::<(), String>(()),
                _ = ticker.tick() => {
                    if let Err(error) = recorder.probe() {
                        return Err(format!("recorder worker stopped: {error}"));
                    }
                    let now = Instant::now();
                    let desired_partition_id = state
                        .account_partition
                        .as_ref()
                        .map(|partition| partition.partition_id.as_str());
                    let recorder_work_pending = state.has_pending_recorder_batch();
                    let recorder_attempt = recorder_attempt_due(now, recorder_retry_at)
                        && (recorder_work_pending
                            || desired_partition_id != active_recorder_partition.as_deref());
                    let result = resident_service_cycle_with_recorder_attempt_v3(
                        &mut state,
                        &mut publication,
                        recorder_attempt,
                        |state, pending| {
                            let batch_is_empty = pending.is_empty();
                            let PendingRecorderBatch {
                                auth_epoch,
                                admission,
                                partition_id,
                                collector_epoch,
                                cycle_seq,
                                bounded_source_rescan_complete,
                                samples,
                                observations,
                                recorded_sessions,
                                session_checkpoints,
                                session_ranges,
                                session_model_totals,
                                history_continuity_recovery,
                                reset_at,
                                window_seconds,
                                cleanup_plans,
                            } = pending;
                            let current_admission = state.current_account_admission();
                            if !batch_is_empty
                                && (auth_epoch != Some(state.auth_epoch)
                                    || admission.as_ref() != current_admission.as_ref()
                                    || partition_id.as_deref()
                                        != current_admission.as_ref().map(|current| {
                                            current.partition_id.as_str()
                                        }))
                            {
                                state.apply_identity_error(
                                    "保存batchのアカウント世代が失効しました。".into(),
                                );
                                let _ = recorder.deactivate_partition();
                                active_recorder_partition = None;
                                return Err("recorder batch admission mismatch".into());
                            }
                            let desired_partition = state.account_partition.clone();
                            let desired_id = desired_partition
                                .as_ref()
                                .map(|partition| partition.partition_id.clone());
                            if desired_id != active_recorder_partition {
                                let activation = match desired_partition {
                                    Some(partition) => recorder
                                        .activate_partition(partition, Utc::now()),
                                    None => recorder.deactivate_partition(),
                                };
                                if let Err(error) = activation {
                                    let _ = recorder.deactivate_partition();
                                    active_recorder_partition = None;
                                    state.apply_identity_error(
                                        "アカウント別DBを安全に有効化できませんでした。".into(),
                                    );
                                    return Err(error);
                                }
                                active_recorder_partition = desired_id;
                            }
                            if collector_epoch.is_some()
                                || cycle_seq.is_some()
                                || !samples.is_empty()
                                || !observations.is_empty()
                                || !recorded_sessions.is_empty()
                                || !session_checkpoints.is_empty()
                                || !session_ranges.is_empty()
                                || !session_model_totals.is_empty()
                                || history_continuity_recovery.is_some()
                            {
                                let Some(batch_partition_id) = partition_id.as_ref() else {
                                    state.apply_identity_error(
                                        "保存batchにアカウントpartitionがありません。".into(),
                                    );
                                    let _ = recorder.deactivate_partition();
                                    active_recorder_partition = None;
                                    return Err("recorder batch has no account partition".into());
                                };
                                if active_recorder_partition.as_deref()
                                    != Some(batch_partition_id.as_str())
                                {
                                    state.apply_identity_error(
                                        "保存batchと有効なアカウントpartitionが一致しません。".into(),
                                    );
                                    let _ = recorder.deactivate_partition();
                                    active_recorder_partition = None;
                                    return Err("recorder batch account partition mismatch".into());
                                }
                                let commit_ack = match recorder.store_generation(
                                    batch_partition_id.clone(),
                                    daemon::RecorderGeneration {
                                        reset_at: reset_at.ok_or_else(|| {
                                            "recorder batch reset period is missing".to_owned()
                                        })?,
                                        window_seconds: window_seconds.ok_or_else(|| {
                                            "recorder batch window is missing".to_owned()
                                        })?,
                                        collector_epoch: collector_epoch.ok_or_else(|| {
                                            "recorder batch collector epoch is missing".to_owned()
                                        })?,
                                        cycle_seq: cycle_seq.ok_or_else(|| {
                                            "recorder batch cycle sequence is missing".to_owned()
                                        })?,
                                        samples,
                                        observations,
                                        recorded_sessions,
                                        session_checkpoints,
                                        session_ranges,
                                        session_model_totals,
                                        history_continuity_recovery,
                                        bounded_source_rescan_complete,
                                    },
                                ) {
                                    Ok(ack) => ack,
                                    Err(error) => {
                                        // Keep the admitted account and active
                                        // writer lane intact. The outer cycle
                                        // restores this exact batch and gates
                                        // the next database attempt by the
                                        // normal recorder interval. Storage
                                        // failure degrades publication; it
                                        // does not terminate the resident
                                        // recorder.
                                        return Err(error);
                                    }
                                };
                                let Some(batch_admission) = admission.as_ref() else {
                                    return Err("recorder batch admission disappeared after commit".into());
                                };
                                let canonical_samples = commit_ack.canonical_samples.clone();
                                let canonical_observations =
                                    commit_ack.canonical_observations.clone();
                                let legacy_history_bridged = commit_ack.legacy_history_bridged;
                                state.acknowledge_recorder_commit(batch_admission, commit_ack);
                                let refreshed = if legacy_history_bridged {
                                    state.history.refresh_from_store(Utc::now())
                                } else {
                                    state.history.apply_committed_samples(
                                        canonical_samples,
                                        Utc::now(),
                                    ) && state.history.apply_committed_observations(
                                        canonical_observations,
                                        Utc::now(),
                                    )
                                };
                                if !refreshed {
                                    return Err("history refresh after recorder commit failed".into());
                                }
                            }
                            if !batch_is_empty && !state.refresh_history_gaps() {
                                return Err("history gap refresh after recorder commit failed".into());
                            }
                            for plan in cleanup_plans {
                                let Some(database) = state.history.db_path.as_deref() else {
                                    debug_runtime("session cleanup retained all files: database unavailable");
                                    continue;
                                };
                                let Some(partition_identity) =
                                    state.history.partition_identity.as_ref()
                                else {
                                    state.apply_identity_error(
                                        "Session cleanupの保存partitionを確認できませんでした。"
                                            .into(),
                                    );
                                    return Err("cleanup partition identity is missing".into());
                                };
                                let report = cleanup_recorded_session_overflow_partitioned(
                                    database,
                                    partition_identity,
                                    &plan,
                                    Path::new("/proc"),
                                );
                                let deleted_count = report.deleted.len();
                                if deleted_count > 0
                                    && recorder
                                        .forget_recorded_sessions(
                                            partition_id.clone().ok_or_else(|| {
                                                "cleanup partition is missing".to_owned()
                                            })?,
                                            report.deleted,
                                        )
                                        .is_err()
                                {
                                    debug_runtime(format!(
                                        "session cleanup marker retirement failed deleted={deleted_count}"
                                    ));
                                }
                                debug_runtime(format!(
                                    "session cleanup deleted={deleted_count} retained={} database_failed={} process_scan_failed={}",
                                    report.retained,
                                    report.database_failed,
                                    report.process_scan_failed
                                ));
                            }
                            Ok(())
                        },
                        |candidate, candidate_v2, candidate_v3| {
                            if candidate.state == PublicState::Ready
                                && !recorder.owner_is_live()
                            {
                                return Err(
                                    codex_info::server::ApiSnapshotError::Serialization,
                                );
                            }
                            publisher.publish_details_v3(candidate, candidate_v2, candidate_v3)
                        },
                    );
                    match result {
                        Ok(outcome) => {
                            if recorder_attempt {
                                recorder_retry_at = None;
                                if last_recorder_error.take().is_some() {
                                    eprintln!("codex-info: recorder state commit recovered");
                                }
                            }
                            if outcome == ResidentServiceCycleOutcome::Published
                                && last_publish_error.take().is_some()
                            {
                                eprintln!("codex-info: REST snapshot publication recovered");
                            }
                        }
                        Err(ResidentServiceCycleError::Store(error)) => {
                            if last_recorder_error.as_deref() != Some(error.as_str()) {
                                eprintln!("codex-info: recorder state commit rejected: {error}");
                                last_recorder_error = Some(error.clone());
                            }
                            // A response timeout cannot distinguish a busy
                            // serialized writer from a dead one. Keep the
                            // exact pending batch and the last-good public
                            // root, then retry once at the normal recorder
                            // interval. Actual thread death is detected by
                            // recorder.probe() on the one-second owner loop.
                            recorder_retry_at = Some(
                                Instant::now()
                                    + daemon::daemon_interval_from_environment(),
                            );
                        }
                        Err(ResidentServiceCycleError::Candidate(error)) => {
                            eprintln!(
                                "codex-info: REST snapshot canonicalization rejected: {error}"
                            );
                        }
                        Err(ResidentServiceCycleError::Publish(error)) => {
                            if last_publish_error != Some(error) {
                                eprintln!("codex-info: REST snapshot publication rejected: {error}");
                                last_publish_error = Some(error);
                            }
                        }
                    }
                }
            }
        }
    });
    if let Some(gap) = pending_gap_for_shutdown(&state, active_recorder_partition.as_deref()) {
        if let Err(error) = recorder.begin_gap(gap.partition_id.clone(), gap) {
            eprintln!("codex-info: recorder stop gap was not persisted: {error}");
        }
    }
    api_server.shutdown();
    recorder.shutdown();
    runtime_result.map_err(std::io::Error::other)?;
    Ok(())
}

fn run_service_mode(config: ApiServerConfig) -> Result<(), Box<dyn std::error::Error>> {
    let address = config.listen_addr();
    if systemd_managed_activation() {
        if reconcile_managed_service_owner(address).map_err(std::io::Error::other)? {
            eprintln!(
                "codex-info: {}",
                I18n::detect().cli_text(CliTextKey::ServiceReused)
            );
            return Ok(());
        }
    } else {
        retire_different_version_service(address).map_err(std::io::Error::other)?;
        if healthy_combined_service_owner(address).is_some() {
            eprintln!(
                "codex-info: {}",
                I18n::detect().cli_text(CliTextKey::ServiceReused)
            );
            return Ok(());
        }
    }
    run_combined_service(config)
}

fn stop_service_mode() -> Result<(), Box<dyn std::error::Error>> {
    daemon::stop_daemon().map_err(|error| {
        let key = match error {
            daemon::StopError::LockUnavailable => CliTextKey::StopLockUnavailable,
            daemon::StopError::LockInvalid => CliTextKey::StopLockInvalid,
            daemon::StopError::OwnerChanged => CliTextKey::StopOwnerChanged,
            daemon::StopError::SignalFailed => CliTextKey::StopSignalFailed,
            daemon::StopError::Timeout => CliTextKey::StopTimeout,
            daemon::StopError::Unsupported => CliTextKey::StopUnsupported,
        };
        std::io::Error::other(cli_error(key)).into()
    })
}

fn run_ui(
    initial_service_error: Option<String>,
    service_config: ApiServerConfig,
    client_only: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    let ui = MainWindow::new()?;
    install_fixed_window_guard(ui.window());
    place_main_window_on_primary_monitor(ui.window());
    let preview_size = std::env::var("CODEX_INFO_PREVIEW_SIZE")
        .ok()
        .and_then(|value| parse_preview_size(Some(value.as_str())));
    let graph_preview_size = preview_size.map(clamp_graph_preview_size);
    let preview_kind = std::env::var("CODEX_INFO_PREVIEW").ok();
    let state = Rc::new(RefCell::new(
        preview_kind
            .clone()
            .map(|kind| CodexInfoState::preview(&kind))
            .unwrap_or_else(CodexInfoState::service_client),
    ));
    if let Some(error) = initial_service_error {
        // A failed --ui service must not make the GUI disappear. Publish a
        // visible retry/error state and keep the window available for recovery.
        state.borrow_mut().hold_service_endpoint_error(error);
    }
    // One graph window owns the three model toggles. The initial state keeps
    // every series enabled, preserving the combined cumulative view.
    let graph_window = Rc::new(RefCell::new(None::<GraphWindow>));
    let graph_maximize_state = Rc::new(RefCell::new(GraphMaximizeState::default()));
    let threads_window = Rc::new(RefCell::new(None::<ThreadsWindow>));
    let legal_notice_window = Rc::new(RefCell::new(None::<LegalNoticeWindow>));
    let x11_monitor = Rc::new(X11WindowStateMonitor::connect());
    let service_retry_in_flight = Arc::new(AtomicBool::new(false));

    {
        let weak_ui = ui.as_weak();
        ui.on_begin_window_drag(move || {
            if let Some(ui) = weak_ui.upgrade() {
                begin_window_drag(ui.window());
            }
        });
    }
    {
        let weak_ui = ui.as_weak();
        ui.on_minimize_window(move || {
            if let Some(ui) = weak_ui.upgrade() {
                minimize_window(ui.window());
            }
        });
    }
    {
        let weak_ui = ui.as_weak();
        ui.on_close_window(move || {
            if let Some(ui) = weak_ui.upgrade() {
                let _ = ui.hide();
            }
            let _ = slint::quit_event_loop();
        });
    }

    {
        let state = Rc::clone(&state);
        ui.on_begin_auth(move || state.borrow_mut().open_auth());
    }
    {
        let state = Rc::clone(&state);
        ui.on_check_auth(move || {
            state
                .borrow_mut()
                .request_service_read("認証状態を確認しています…")
        });
    }
    {
        let state = Rc::clone(&state);
        let service_retry_in_flight = Arc::clone(&service_retry_in_flight);
        ui.on_retry(move || {
            let mut state = state.borrow_mut();
            if state.service_endpoint_error.is_some() {
                if client_only {
                    // The verified launcher fallback is explicitly a UI
                    // client. Retry only the selected endpoint; allowing this
                    // callback to spawn a raw `--port` child would recreate
                    // the resident owner after the launcher reported failure.
                    state.request_service_read("利用状況を更新しています…");
                } else {
                    start_background_service_retry(
                        &mut state,
                        service_config,
                        &service_retry_in_flight,
                        ensure_background_service,
                    );
                }
            } else {
                state.request_service_read("利用状況を更新しています…");
            }
        });
    }
    {
        let state = Rc::clone(&state);
        let graph_window = Rc::clone(&graph_window);
        let graph_maximize_state = Rc::clone(&graph_maximize_state);
        let x11_monitor = Rc::clone(&x11_monitor);
        let graph_old_preview = preview_kind.as_deref() == Some("graph-old");
        let graph_period_preview =
            matches!(preview_kind.as_deref(), Some("graph-period" | "graph-many"));
        ui.on_open_graph(move || {
            if !graph_old_preview {
                state.borrow_mut().select_latest_history();
            }
            let mut graph_window = graph_window.borrow_mut();
            if graph_window.is_none() {
                if let Ok(graph) = GraphWindow::new() {
                    graph.set_open_history_on_start(graph_period_preview);
                    let (graph_width, graph_height) =
                        graph_preview_size.unwrap_or((GRAPH_WINDOW_WIDTH, GRAPH_WINDOW_HEIGHT));
                    if graph_preview_size.is_some() {
                        graph.window().set_size(slint::LogicalSize::new(
                            graph_width as f32,
                            graph_height as f32,
                        ));
                    }
                    install_resizable_window(graph.window());
                    let weak_graph = graph.as_weak();
                    graph.on_begin_window_drag(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            begin_window_drag(graph.window());
                        }
                    });
                    let weak_graph = graph.as_weak();
                    graph.on_begin_window_resize(move |direction| {
                        if let Some(graph) = weak_graph.upgrade() {
                            begin_window_resize(graph.window(), direction.as_str());
                        }
                    });
                    let weak_graph = graph.as_weak();
                    graph.on_minimize_window(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            minimize_window(graph.window());
                        }
                    });
                    let weak_graph = graph.as_weak();
                    let graph_maximize_state = Rc::clone(&graph_maximize_state);
                    graph.on_toggle_maximize_window(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            toggle_graph_maximize(graph.window(), &graph, &graph_maximize_state);
                        }
                    });
                    let weak_graph = graph.as_weak();
                    graph.on_close_graph(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            graph.set_reset_close_buttons(true);
                            graph.set_reset_close_buttons(false);
                            let _ = graph.hide();
                        }
                    });
                    let weak_graph = graph.as_weak();
                    graph.on_close_window(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            graph.set_reset_close_buttons(true);
                            graph.set_reset_close_buttons(false);
                            let _ = graph.hide();
                        }
                    });
                    let weak_graph = graph.as_weak();
                    graph.window().on_close_requested(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            graph.set_reset_close_buttons(true);
                            graph.set_reset_close_buttons(false);
                            if graph.hide().is_ok() {
                                return CloseRequestResponse::KeepWindowShown;
                            }
                        }
                        CloseRequestResponse::HideWindow
                    });
                    let weak_graph = graph.as_weak();
                    let state_for_toggle = Rc::clone(&state);
                    graph.on_toggle_remaining(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            graph.set_show_remaining(!graph.get_show_remaining());
                            sync_graph_window(&state_for_toggle.borrow(), &graph);
                        }
                    });
                    let weak_graph = graph.as_weak();
                    let state_for_metric = Rc::clone(&state);
                    graph.on_select_metric(move |metric| {
                        if let Some(graph) = weak_graph.upgrade() {
                            state_for_metric.borrow_mut().select_metric(&metric);
                            sync_graph_window(&state_for_metric.borrow(), &graph);
                        }
                    });
                    let weak_graph = graph.as_weak();
                    let state_for_toggle = Rc::clone(&state);
                    graph.on_toggle_luna(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            graph.set_show_luna(!graph.get_show_luna());
                            sync_graph_window(&state_for_toggle.borrow(), &graph);
                        }
                    });
                    let weak_graph = graph.as_weak();
                    let state_for_toggle = Rc::clone(&state);
                    graph.on_toggle_terra(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            graph.set_show_terra(!graph.get_show_terra());
                            sync_graph_window(&state_for_toggle.borrow(), &graph);
                        }
                    });
                    let weak_graph = graph.as_weak();
                    let state_for_toggle = Rc::clone(&state);
                    graph.on_toggle_sol(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            graph.set_show_sol(!graph.get_show_sol());
                            sync_graph_window(&state_for_toggle.borrow(), &graph);
                        }
                    });
                    let weak_graph = graph.as_weak();
                    let state_for_toggle = Rc::clone(&state);
                    graph.on_toggle_astra(move || {
                        if let Some(graph) = weak_graph.upgrade() {
                            graph.set_show_astra(!graph.get_show_astra());
                            sync_graph_window(&state_for_toggle.borrow(), &graph);
                        }
                    });
                    let weak_graph = graph.as_weak();
                    let state_for_history = Rc::clone(&state);
                    graph.on_select_history(move |label| {
                        if let Some(graph) = weak_graph.upgrade() {
                            state_for_history
                                .borrow_mut()
                                .select_history(label.as_str());
                            sync_graph_window(&state_for_history.borrow(), &graph);
                        }
                    });
                    *graph_window = Some(graph);
                }
            }
            if let Some(graph) = graph_window.as_ref() {
                graph.set_reset_close_buttons(true);
                graph.set_reset_close_buttons(false);
                sync_graph_window(&state.borrow(), graph);
                let _ = show_and_focus_window(graph.window(), x11_monitor.as_ref().as_ref());
                if let Some(monitor) = x11_monitor.as_ref() {
                    monitor.allow_resize(graph.window());
                }
            }
        });
    }
    {
        let state = Rc::clone(&state);
        let threads_window = Rc::clone(&threads_window);
        let x11_monitor = Rc::clone(&x11_monitor);
        ui.on_open_threads(move || {
            let mut threads_window = threads_window.borrow_mut();
            if threads_window.is_none() {
                if let Ok(window) = ThreadsWindow::new() {
                    install_fixed_window_guard(window.window());
                    let weak_window = window.as_weak();
                    window.on_begin_window_drag(move || {
                        if let Some(window) = weak_window.upgrade() {
                            begin_window_drag(window.window());
                        }
                    });
                    let weak_window = window.as_weak();
                    window.on_minimize_window(move || {
                        if let Some(window) = weak_window.upgrade() {
                            minimize_window(window.window());
                        }
                    });
                    let weak_window = window.as_weak();
                    window.on_close_threads(move || {
                        if let Some(window) = weak_window.upgrade() {
                            window.set_reset_close_buttons(true);
                            window.set_reset_close_buttons(false);
                            let _ = window.hide();
                        }
                    });
                    let weak_window = window.as_weak();
                    window.on_close_window(move || {
                        if let Some(window) = weak_window.upgrade() {
                            window.set_reset_close_buttons(true);
                            window.set_reset_close_buttons(false);
                            let _ = window.hide();
                        }
                    });
                    let weak_window = window.as_weak();
                    window.window().on_close_requested(move || {
                        if let Some(window) = weak_window.upgrade() {
                            window.set_reset_close_buttons(true);
                            window.set_reset_close_buttons(false);
                            if window.hide().is_ok() {
                                return CloseRequestResponse::KeepWindowShown;
                            }
                        }
                        CloseRequestResponse::HideWindow
                    });
                    *threads_window = Some(window);
                }
            }
            if let Some(window) = threads_window.as_ref() {
                window.set_reset_close_buttons(true);
                window.set_reset_close_buttons(false);
                sync_threads_window(&state.borrow(), window);
                let _ = show_and_focus_window(window.window(), x11_monitor.as_ref().as_ref());
            }
        });
    }
    {
        let state = Rc::clone(&state);
        let legal_notice_window = Rc::clone(&legal_notice_window);
        let x11_monitor = Rc::clone(&x11_monitor);
        ui.on_open_legal_notice(move || {
            let mut legal_notice_window = legal_notice_window.borrow_mut();
            if legal_notice_window.is_none() {
                if let Ok(window) = LegalNoticeWindow::new() {
                    install_window_size_guard(
                        window.window(),
                        LEGAL_WINDOW_WIDTH,
                        LEGAL_WINDOW_HEIGHT,
                    );
                    let weak_window = window.as_weak();
                    window.on_begin_window_drag(move || {
                        if let Some(window) = weak_window.upgrade() {
                            begin_window_drag(window.window());
                        }
                    });
                    let weak_window = window.as_weak();
                    window.on_minimize_window(move || {
                        if let Some(window) = weak_window.upgrade() {
                            minimize_window(window.window());
                        }
                    });
                    let weak_window = window.as_weak();
                    window.on_close_legal_notice(move || {
                        if let Some(window) = weak_window.upgrade() {
                            window.set_reset_close_buttons(true);
                            window.set_reset_close_buttons(false);
                            let _ = window.hide();
                        }
                    });
                    let weak_window = window.as_weak();
                    window.on_close_window(move || {
                        if let Some(window) = weak_window.upgrade() {
                            window.set_reset_close_buttons(true);
                            window.set_reset_close_buttons(false);
                            let _ = window.hide();
                        }
                    });
                    let weak_window = window.as_weak();
                    window.on_legal_page_back(move || {
                        if let Some(window) = weak_window.upgrade() {
                            let index = window.get_legal_page_index();
                            window.set_legal_page_index(index.saturating_sub(1));
                        }
                    });
                    let weak_window = window.as_weak();
                    window.on_legal_page_next(move || {
                        if let Some(window) = weak_window.upgrade() {
                            let index = window.get_legal_page_index();
                            let page_count = window.get_strings().legal_pages.row_count();
                            if index + 1 < i32::try_from(page_count).unwrap_or(i32::MAX) {
                                window.set_legal_page_index(index.saturating_add(1));
                            }
                        }
                    });
                    let weak_window = window.as_weak();
                    window.window().on_close_requested(move || {
                        if let Some(window) = weak_window.upgrade() {
                            window.set_reset_close_buttons(true);
                            window.set_reset_close_buttons(false);
                            if window.hide().is_ok() {
                                return CloseRequestResponse::KeepWindowShown;
                            }
                        }
                        CloseRequestResponse::HideWindow
                    });
                    *legal_notice_window = Some(window);
                }
            }
            if let Some(window) = legal_notice_window.as_ref() {
                let state_ref = state.borrow();
                window.set_strings(ui_strings(&state_ref.i18n));
                window.set_window_title(
                    native_detail_window_title(
                        &state_ref.i18n,
                        state_ref.authenticated,
                        &state_ref.window_title(),
                        WindowPurpose::Legal,
                    )
                    .into(),
                );
                window.set_legal_page_index(0);
                window.set_reset_close_buttons(true);
                window.set_reset_close_buttons(false);
                let _ = show_and_focus_window(window.window(), x11_monitor.as_ref().as_ref());
            }
        });
    }

    if matches!(
        preview_kind.as_deref(),
        Some("graph" | "graph-old" | "graph-many" | "graph-period" | "graph-collision")
    ) {
        if preview_kind.as_deref() == Some("graph-old") {
            state.borrow_mut().select_latest_history();
            state.borrow_mut().select_older_history();
        }
        ui.invoke_open_graph();
    }
    if matches!(
        preview_kind.as_deref(),
        Some("multi-thread" | "single-thread")
    ) {
        ui.invoke_open_threads();
    }
    if preview_kind.as_deref() == Some("legal") {
        ui.invoke_open_legal_notice();
    }

    state.borrow().sync_ui(&ui);
    let weak_ui_for_bounds = ui.as_weak();
    let monitor = Rc::clone(&x11_monitor);
    let graph_window_for_resize = Rc::clone(&graph_window);
    let threads_window_for_bounds = Rc::clone(&threads_window);
    let legal_notice_window_for_bounds = Rc::clone(&legal_notice_window);
    let main_monitor_timer = Timer::default();
    main_monitor_timer.start(TimerMode::Repeated, Duration::from_millis(100), move || {
        if let Some(ui) = weak_ui_for_bounds.upgrade() {
            if let Some(monitor) = monitor.as_ref() {
                monitor.enforce(ui.window());
                if let Some(graph) = graph_window_for_resize.borrow().as_ref() {
                    if graph.window().is_visible() {
                        monitor.allow_resize(graph.window());
                    }
                }
                if let Some(window) = threads_window_for_bounds.borrow().as_ref() {
                    if window.window().is_visible() {
                        monitor.enforce(window.window());
                    }
                }
                if let Some(window) = legal_notice_window_for_bounds.borrow().as_ref() {
                    if window.window().is_visible() {
                        monitor.enforce(window.window());
                    }
                }
            }
        }
    });
    let weak_ui_for_position = ui.as_weak();
    let main_window_position_timer = Timer::default();
    main_window_position_timer.start(
        TimerMode::SingleShot,
        Duration::from_millis(100),
        move || {
            if let Some(ui) = weak_ui_for_position.upgrade() {
                place_main_window_on_primary_monitor(ui.window());
            }
        },
    );
    let weak_ui = ui.as_weak();
    let graph_window_for_timer = Rc::clone(&graph_window);
    let threads_window_for_timer = Rc::clone(&threads_window);
    let service_retry_for_timer = Arc::clone(&service_retry_in_flight);
    let timer = Timer::default();
    if !state.borrow().preview {
        timer.start(TimerMode::Repeated, Duration::from_secs(1), move || {
            if let Some(ui) = weak_ui.upgrade() {
                let mut state = state.borrow_mut();
                if !service_retry_for_timer.load(Ordering::Acquire) {
                    run_ui_service_timer_cycle(&mut state, service_config.listen_addr());
                }
                state.sync_ui(&ui);
                if let Some(graph) = graph_window_for_timer.borrow().as_ref() {
                    if graph.window().is_visible() {
                        sync_graph_window(&state, graph);
                    }
                }
                if let Some(window) = threads_window_for_timer.borrow().as_ref() {
                    if window.window().is_visible() {
                        sync_threads_window(&state, window);
                    }
                }
            }
        });
    }
    ui.run()?;
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let arguments = std::env::args_os().skip(1).collect::<Vec<_>>();
    let mode = parse_launch_mode(arguments).map_err(std::io::Error::other)?;
    match mode {
        LaunchMode::Service(config) => run_service_mode(config),
        LaunchMode::Stop => stop_service_mode(),
        LaunchMode::All(config) => {
            let client_only = ui_client_only_mode().map_err(std::io::Error::other)?;
            let startup_error = if client_only {
                // The installed launcher has already performed generation,
                // payload, and owner verification.  Preserve the existing
                // localized failure/retry surface while this process only
                // polls the selected endpoint and never starts a resident.
                Some(cli_error(CliTextKey::ServiceStartFailed))
            } else {
                ensure_background_service(config).err()
            };
            run_ui(startup_error, config, client_only)
        }
        LaunchMode::Help => {
            let language = I18n::detect().language();
            let help =
                if std::env::var_os("CODEX_INFO_LAUNCHER_HELP").is_some_and(|value| value == "1") {
                    language.launcher_help()
                } else {
                    language.launch_help()
                };
            println!("{help}");
            Ok(())
        }
    }
}

