    #[test]
    fn ui_polling_holds_selected_endpoint_error_until_that_endpoint_is_healthy() {
        let blocker = TcpListener::bind("127.0.0.1:0").unwrap();
        let endpoint = blocker.local_addr().unwrap();
        let mut state = CodexInfoState::preview("normal");
        let ready_details = state.public_details();
        state.preview = false;
        state.hold_service_endpoint_error("selected endpoint unavailable".into());

        poll_service_state_with_owner_check(&mut state, endpoint, |_| false);
        assert_eq!(
            state.service_endpoint_error.as_deref(),
            Some("selected endpoint unavailable")
        );

        drop(blocker);
        let mut server =
            ApiServer::start(ApiServerConfig::new(endpoint).unwrap()).expect("selected endpoint");
        server.publisher().publish_details(ready_details).unwrap();
        poll_service_state(&mut state, endpoint);
        assert_eq!(
            state.service_endpoint_error.as_deref(),
            Some("selected endpoint unavailable"),
            "HTTP health without a verified resident owner must remain rejected"
        );
        poll_service_state_with_owner_check(&mut state, endpoint, service_is_healthy);
        assert!(state.service_endpoint_error.is_none());
        let admitted_pair = state.service_published_pair.clone();
        let admitted_details = state.public_details();
        let admitted_status = state.display_status();

        state.hold_service_endpoint_error("same endpoint failed once".into());
        assert!(state.has_display_error());
        assert_eq!(state.status_level(), "error");
        assert_ne!(state.display_status(), admitted_status);
        assert_eq!(state.service_published_pair, admitted_pair);
        assert_eq!(state.public_details(), admitted_details);

        poll_service_state_with_owner_check(&mut state, endpoint, service_is_healthy);
        assert!(state.service_endpoint_error.is_none());
        assert!(!state.has_display_error());
        assert_eq!(state.display_status(), admitted_status);
        assert_eq!(state.service_published_pair, admitted_pair);
        assert_eq!(state.public_details(), admitted_details);
        server.shutdown();
    }

    #[test]
    fn explicit_service_retry_starts_once_without_replacing_last_good_data() {
        let mut state = CodexInfoState::preview("normal");
        state.preview = false;
        state.service_published_pair = Some("pair:7".into());
        state.hold_service_endpoint_error("selected endpoint unavailable".into());
        let admitted_details = state.public_details();
        let in_flight = Arc::new(AtomicBool::new(false));
        let (started_tx, started_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let config = ApiServerConfig::new("127.0.0.1:18787".parse().unwrap()).unwrap();

        assert!(super::start_background_service_retry(
            &mut state,
            config,
            &in_flight,
            move |started_config| {
                started_tx.send(started_config.listen_addr()).unwrap();
                release_rx.recv().unwrap();
                Ok(())
            },
        ));
        assert_eq!(
            started_rx.recv_timeout(Duration::from_secs(1)).unwrap(),
            config.listen_addr()
        );
        assert!(!super::start_background_service_retry(
            &mut state,
            config,
            &in_flight,
            |_| Ok(()),
        ));
        assert!(state.checking);
        assert!(state.has_display_error());
        assert_eq!(state.public_details(), admitted_details);

        release_tx.send(()).unwrap();
        let deadline = Instant::now() + Duration::from_secs(1);
        while in_flight.load(Ordering::Acquire) && Instant::now() < deadline {
            std::thread::yield_now();
        }
        assert!(!in_flight.load(Ordering::Acquire));
    }

    #[test]
    fn service_health_requires_a_complete_success_json_body_without_waiting_for_eof() {
        let valid = format!(
            "HTTP/1.1 200 OK\r\nConnection: keep-alive\r\n\r\n{{\"api_version\":\"v1\",\"service\":\"codex-info\",\"product_version\":\"{PRODUCT_VERSION}\"}}"
        );
        assert!(is_service_health_response(valid.as_bytes()));
        assert_eq!(
            service_health_response_version(
                b"HTTP/1.1 200 OK\r\n\r\n{\"api_version\":\"v1\",\"service\":\"codex-info\"}"
            ),
            Some(ServiceHealthVersion::Different)
        );
        assert_eq!(
            service_health_response_version(
                b"HTTP/1.1 200 OK\r\n\r\n{\"api_version\":\"v1\",\"service\":\"codex-info\",\"product_version\":\"0.0.0\"}"
            ),
            Some(ServiceHealthVersion::Different)
        );
        assert_eq!(
            service_health_response_version(
                b"HTTP/1.1 200 OK\r\n\r\n{\"api_version\":\"v1\",\"service\":\"codex-info\",\"product_version\":\"x\"}"
            ),
            None
        );
        assert_eq!(
            service_health_response_version(
                b"HTTP/1.1 200 OK\r\n\r\n{\"api_version\":\"v1\",\"service\":\"codex-info\",\"product_version\":\"01.0.18\"}"
            ),
            None
        );
        assert_eq!(
            service_health_response_version(
                b"HTTP/1.1 200 OK\r\n\r\n{\"api_version\":\"v1\",\"service\":\"codex-info\",\"product_version\":\"1.0.18\",\"extra\":true}"
            ),
            None
        );
        assert_eq!(
            service_health_response_version(
                b"HTTP/1.1 200 OK\r\n\r\n{\"api_version\":\"v1\",\"service\":\"codex-info\",\"product_version\":\"1.0.18\",\"product_version\":\"1.0.18\"}"
            ),
            None
        );
        assert!(!is_service_health_response(
            b"HTTP/1.1 200 OK\r\nX-Service: codex-info\r\n\r\n{}"
        ));
        assert!(!is_service_health_response(
            b"HTTP/1.1 500 Error\r\n\r\n{\"api_version\":\"v1\",\"service\":\"codex-info\"}"
        ));
        assert!(!is_service_health_response(
            b"HTTP/1.1 200 OK\r\n\r\n{\"api_version\":\"v1\",\"service\":\"codex-info\""
        ));
    }

