        state.local_usage_pending = true;
        state.apply_local_usage_error_with_generation(
            state.auth_epoch,
            Some(admission),
            reset_at,
            WEEK_SECONDS,
            Some(0x13a),
            Some(5),
            Vec::new(),
        );
        assert!(!state.local_usage_pending);
        assert!(state.history.pending_store_samples.is_empty());
        assert!(!state.has_pending_recorder_batch());
