    #[test]
    fn thread_age_uses_fixed_boundaries_and_clamps_future() {
        let now = 86_400;
        assert_eq!(format_elapsed(now, Some(now)), "0秒");
        assert_eq!(format_elapsed(now, Some(now - 59)), "59秒");
        assert_eq!(format_elapsed(now, Some(now - 60)), "1分");
        assert_eq!(format_elapsed(now, Some(now - 83)), "1分23秒");
        assert_eq!(format_elapsed(now, Some(now - 3_599)), "59分59秒");
        assert_eq!(format_elapsed(now, Some(now - 3_600)), "1時間");
        assert_eq!(format_elapsed(now, Some(now - 3_661)), "1時間1分");
        assert_eq!(format_elapsed(now, Some(now - 86_399)), "23時間59分");
        assert_eq!(format_elapsed(now, Some(now - 86_400)), "1日");
        assert_eq!(format_elapsed(now, Some(now + 60)), "0秒");
        assert_eq!(format_elapsed(now, Some(i64::MAX)), "—");
        assert_eq!(format_elapsed(now, None), "—");
    }

    #[cfg(unix)]
    #[test]
    fn open_codex_session_paths_accepts_only_bounded_codex_fds_under_sessions_root() {
        use std::os::unix::fs::symlink;

        static NEXT_ROOT: AtomicU64 = AtomicU64::new(0);
        let root = std::env::temp_dir().join(format!(
            "codex-info-proc-fixture-{}-{}",
            std::process::id(),
            NEXT_ROOT.fetch_add(1, Ordering::Relaxed)
        ));
        let sessions = root.join("sessions");
        let proc_root = root.join("proc");
        let process = proc_root.join("100");
        let ignored_process = proc_root.join("200");
        let disappeared_process = proc_root.join("300");
        fs::create_dir_all(process.join("fd")).unwrap();
        fs::create_dir_all(ignored_process.join("fd")).unwrap();
        fs::create_dir_all(&disappeared_process).unwrap();
        fs::create_dir_all(&sessions).unwrap();
        fs::write(process.join("comm"), "codex\n").unwrap();
        fs::write(ignored_process.join("comm"), "not-codex\n").unwrap();
        let executable = root.join("codex");
        fs::write(&executable, "fixture").unwrap();
        symlink(&executable, process.join("exe")).unwrap();
        symlink(&executable, ignored_process.join("exe")).unwrap();
        let active = sessions.join("active.jsonl");
        let ignored = sessions.join("ignored.jsonl");
        let outside = root.join("outside.jsonl");
        fs::write(&active, "{}\n").unwrap();
        fs::write(&ignored, "{}\n").unwrap();
        fs::write(&outside, "{}\n").unwrap();
        symlink(&active, process.join("fd/3")).unwrap();
        symlink(&outside, process.join("fd/4")).unwrap();
        symlink(&ignored, ignored_process.join("fd/3")).unwrap();

        assert_eq!(
            open_codex_session_paths(&proc_root, &sessions).unwrap(),
            BTreeSet::from([fs::canonicalize(active).unwrap()])
        );

        // `NotFound` is the sole tolerated `/proc` race. An unreadable
        // descriptor entry would make the active set incomplete and must
        // reject the whole scan rather than silently authorize cleanup.
        fs::remove_file(process.join("fd/4")).unwrap();
        fs::write(process.join("fd/4"), "not-a-symlink").unwrap();
        assert!(open_codex_session_paths(&proc_root, &sessions).is_err());
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn recorded_overflow_cleanup_deletes_only_fresh_authorized_files() {
        static NEXT_ROOT: AtomicU64 = AtomicU64::new(0);
        let root = std::env::temp_dir().join(format!(
            "codex-info-session-cleanup-{}-{}",
            std::process::id(),
            NEXT_ROOT.fetch_add(1, Ordering::Relaxed)
        ));
        let sessions = root.join("sessions");
        let history = root.join("history");
        fs::create_dir_all(sessions.join("kept-directory")).unwrap();
        fs::create_dir_all(&history).unwrap();
        for name in [
            "marked",
            "unmarked",
            "changed",
            "active",
            "selected",
            "missing",
            "remove-failure",
        ] {
            fs::write(sessions.join(format!("{name}.jsonl")), "{}\n").unwrap();
        }
        let backup = history.join("usage_history.sqlite3.bak.1");
        let hint = history.join("usage_reset_hint.json");
        let recovery = history.join("delegation_usage_recovery.jsonl");
        fs::write(&backup, b"verified-backup-fixture").unwrap();
        fs::write(&hint, b"reset-hint-fixture").unwrap();
        fs::write(&recovery, b"recovery-fixture\n").unwrap();
        let protected_bytes = (
            fs::read(&backup).unwrap(),
            fs::read(&hint).unwrap(),
            fs::read(&recovery).unwrap(),
        );

        let inventory =
            super::local_input_inventory_for_paths_with_limit(Some(&sessions), None, 0).unwrap();
        let mut plan = super::cleanup_plan_for_inventory(&inventory).unwrap();
        let candidate = |name: &str| {
            plan.overflow_files
                .iter()
                .find(|candidate| {
                    candidate
                        .fingerprint
                        .path
                        .file_stem()
                        .and_then(|value| value.to_str())
                        == Some(name)
                })
                .unwrap()
                .clone()
        };
        let marked = candidate("marked");
        let changed = candidate("changed");
        let active = candidate("active");
        let selected = candidate("selected");
        let missing = candidate("missing");
        let remove_failure = candidate("remove-failure");
        plan.selected_paths
            .insert(selected.fingerprint.path.clone());

        let database = history.join("usage_history.sqlite3");
        let existing = super::usage_store::UsageHistorySample {
            timestamp: 1_700_000_060,
            reset_at: 1_700_604_800,
            remaining_percent: Some(75.0),
            sol_dollars: 1.0,
            terra_dollars: 2.0,
            luna_dollars: 3.0,
            sol_tokens: 11,
            terra_tokens: 22,
            luna_tokens: 33,
        };
        let markers = [
            marked.recorded_source.clone(),
            changed.recorded_source.clone(),
            active.recorded_source.clone(),
            selected.recorded_source.clone(),
            missing.recorded_source.clone(),
            remove_failure.recorded_source.clone(),
        ];
        let mut store = UsageStore::open(&database).unwrap();
        store
            .upsert_samples_and_recorded_sessions(std::slice::from_ref(&existing), &markers)
            .unwrap();
        let durable = store
            .commit_durable_state(&[], "2".repeat(64), "{}")
            .unwrap();
        drop(store);

        let readback_failure = super::cleanup_recorded_session_overflow_with(
            &history.join("missing.sqlite3"),
            &plan,
            Ok(BTreeSet::new()),
            |path| fs::remove_file(path),
        );
        assert!(readback_failure.database_failed);
        assert!(marked.fingerprint.path.exists());
        let scan_failure =
            super::cleanup_recorded_session_overflow_with(&database, &plan, Err(()), |path| {
                fs::remove_file(path)
            });
        assert!(scan_failure.process_scan_failed);
        assert!(marked.fingerprint.path.exists());

        #[cfg(unix)]
        {
            use std::os::unix::fs::symlink;

            let proc_root = root.join("proc-partial");
            let process = proc_root.join("100");
            fs::create_dir_all(process.join("fd")).unwrap();
            fs::write(process.join("comm"), "codex\n").unwrap();
            let executable = root.join("codex");
            fs::write(&executable, "fixture").unwrap();
            symlink(&executable, process.join("exe")).unwrap();
            fs::write(process.join("fd/3"), "not-a-symlink").unwrap();

            let partial_scan =
                super::cleanup_recorded_session_overflow(&database, &plan, &proc_root);
            assert!(partial_scan.process_scan_failed);
            assert!(partial_scan.deleted.is_empty());
            assert!(marked.fingerprint.path.exists());
        }

        let mut changed_append = fs::OpenOptions::new()
            .append(true)
            .open(&changed.fingerprint.path)
            .unwrap();
        writeln!(changed_append, "{{\"changed\":true}}").unwrap();
        drop(changed_append);
        fs::remove_file(&missing.fingerprint.path).unwrap();
        let active_paths = BTreeSet::from([active.fingerprint.path.clone()]);
        let remove_failure_path = remove_failure.fingerprint.path.clone();
        let report = super::cleanup_recorded_session_overflow_with(
            &database,
            &plan,
            Ok(active_paths),
            |path| {
                if path == remove_failure_path {
                    Err(std::io::Error::new(
                        std::io::ErrorKind::PermissionDenied,
                        "injected remove failure",
                    ))
                } else {
                    fs::remove_file(path)
                }
            },
        );
        assert_eq!(
            report.deleted,
            std::slice::from_ref(&marked.recorded_source)
        );
        assert_eq!(report.retained, 6);
        assert!(!marked.fingerprint.path.exists());
        assert!(sessions.join("unmarked.jsonl").exists());
        assert!(changed.fingerprint.path.exists());
        assert!(active.fingerprint.path.exists());
        assert!(selected.fingerprint.path.exists());
        assert!(remove_failure.fingerprint.path.exists());
        assert!(!missing.fingerprint.path.exists());
        assert!(sessions.join("kept-directory").is_dir());

        let connection = rusqlite::Connection::open(&database).unwrap();
        connection
            .execute_batch(
                "CREATE TRIGGER reject_cleanup_marker_delete
                 BEFORE DELETE ON recorded_sessions
                 BEGIN
                    SELECT RAISE(ABORT, 'marker delete rejected');
                 END;",
            )
            .unwrap();
        drop(connection);
        let mut store = UsageStore::open(&database).unwrap();
        assert!(store.forget_recorded_sessions(&report.deleted).is_err());
        assert!(store
            .recorded_session_matches(&marked.recorded_source)
            .unwrap());
        assert_eq!(store.load_all().unwrap(), vec![existing.clone()]);
        assert_eq!(store.load_durable_record().unwrap(), Some(durable.clone()));
        drop(store);
        let connection = rusqlite::Connection::open(&database).unwrap();
        connection
            .execute("DROP TRIGGER reject_cleanup_marker_delete", [])
            .unwrap();
        drop(connection);
        let mut store = UsageStore::open(&database).unwrap();
        assert_eq!(store.forget_recorded_sessions(&report.deleted).unwrap(), 1);
        assert!(!store
            .recorded_session_matches(&marked.recorded_source)
            .unwrap());
        assert_eq!(store.load_all().unwrap(), vec![existing]);
        assert_eq!(store.load_durable_record().unwrap(), Some(durable));
        drop(store);

        assert_eq!(fs::read(&backup).unwrap(), protected_bytes.0);
        assert_eq!(fs::read(&hint).unwrap(), protected_bytes.1);
        assert_eq!(fs::read(&recovery).unwrap(), protected_bytes.2);
        let _ = fs::remove_dir_all(root);
    }

    fn thread_list_item(id: &str, updated_at: i64, path: &Path) -> Value {
        json!({
            "cliVersion": "0.147.0",
            "createdAt": 1,
            "cwd": "/tmp/codex-info",
            "ephemeral": false,
            "id": id,
            "modelProvider": "openai",
            "preview": format!("preview-{id}"),
            "sessionId": format!("session-{id}"),
            "source": "cli",
            "status": {"type": "idle"},
            "turns": [],
            "updatedAt": updated_at,
            "name": format!("title-{id}"),
            "path": path.to_string_lossy()
        })
    }

    #[test]
    fn active_thread_adapter_rejects_partial_rollout_fallback() {
        static NEXT_ROOT: AtomicU64 = AtomicU64::new(0);
        let root = std::env::temp_dir().join(format!(
            "codex-info-thread-adapter-{}-{}",
            std::process::id(),
            NEXT_ROOT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&root).unwrap();
        let newest_path = root.join("newest.jsonl");
        let fallback_path = root.join("fallback.jsonl");
        fs::write(
            &newest_path,
            [
                json!({"type":"session_meta","payload":{"id":"newest"}}).to_string(),
                "{\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\"}}".to_owned(),
            ]
            .join("\n")
                + "\n",
        )
        .unwrap();
        fs::write(
            &fallback_path,
            [
                json!({"type":"session_meta","payload":{"id":"fallback"}}),
                json!({"type":"event_msg","payload":{"type":"task_started"}}),
                json!({"type":"event_msg","payload":{"type":"turn_context","model":"gpt-5.6-sol"}}),
                json!({"type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"total_tokens":12345}}}}),
            ]
            .into_iter()
            .map(|value| value.to_string())
            .collect::<Vec<_>>()
            .join("\n")
                + "\n",
        )
        .unwrap();

        let (sender, receiver) = mpsc::channel();
        sender
            .send(RpcReadEvent::Line(
                super::security::RpcLine::new(
                    json!({
                        "id": 50,
                        "result": {"thread": thread_list_item("fallback", 10, &fallback_path)}
                    })
                    .to_string(),
                )
                .unwrap(),
            ))
            .unwrap();

        let mut input = Vec::new();
        let mut next_id = 50;
        let active_paths = BTreeSet::from([
            fs::canonicalize(&newest_path).unwrap(),
            fs::canonicalize(&fallback_path).unwrap(),
        ]);
        let update = fetch_active_thread_update_for_paths(
            &mut input,
            &receiver,
            &mut next_id,
            &root,
            &active_paths,
        );
        assert_eq!(update, ActiveThreadUpdate::Failed);
        assert_eq!(next_id, 51);

        let requests = String::from_utf8(input)
            .unwrap()
            .lines()
            .map(|line| serde_json::from_str::<Value>(line).unwrap())
            .collect::<Vec<_>>();
        assert_eq!(requests.len(), 1);
        assert_eq!(requests[0]["id"], 50);
        assert_eq!(requests[0]["method"], "thread/read");
        assert_eq!(
            requests[0]["params"],
            json!({"threadId":"fallback","includeTurns":false})
        );
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn multiple_running_threads_are_all_published_with_stable_order() {
        static NEXT_ROOT: AtomicU64 = AtomicU64::new(0);
        let root = std::env::temp_dir().join(format!(
            "codex-info-multiple-running-{}-{}",
            std::process::id(),
            NEXT_ROOT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&root).unwrap();

        let completed_path = root.join("completed.jsonl");
        let running_a_path = root.join("running-a.jsonl");
        let running_z_path = root.join("running-z.jsonl");
        fs::write(
            &completed_path,
            [
                json!({"type":"session_meta","payload":{"id":"completed"}}),
                json!({"type":"task_started"}),
                json!({"type":"task_complete"}),
            ]
            .into_iter()
            .map(|value| value.to_string())
            .collect::<Vec<_>>()
            .join("\n")
                + "\n",
        )
        .unwrap();
        for (path, model, total_tokens) in [
            (&running_a_path, "model-a", 111_u64),
            (&running_z_path, "model-z", 999_u64),
        ] {
            fs::write(
                path,
                [
                    json!({"type":"session_meta","payload":{"id":path.file_stem().unwrap().to_str().unwrap()}}),
                    json!({"type":"thread_context","model":model}),
                    json!({"type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"total_tokens":total_tokens}}}}),
                    json!({"type":"task_started"}),
                ]
                .into_iter()
                .map(|value| value.to_string())
                .collect::<Vec<_>>()
                .join("\n")
                    + "\n",
            )
            .unwrap();
        }

        let mut child_item = thread_list_item("running-a", 20, &running_a_path);
        child_item["source"] = json!({"subAgent":{"thread_spawn":{
            "parent_thread_id":"running-z","depth":1
        }}});
        let (sender, receiver) = mpsc::channel();
        for (id, item) in [
            (70, thread_list_item("completed", 30, &completed_path)),
            (71, child_item),
            (72, thread_list_item("running-z", 20, &running_z_path)),
        ] {
            sender
                .send(RpcReadEvent::Line(
                    super::security::RpcLine::new(
                        json!({"id":id,"result":{"thread":item}}).to_string(),
                    )
                    .unwrap(),
                ))
                .unwrap();
        }

        let mut input = Vec::new();
        let mut next_id = 70;
        let active_paths = BTreeSet::from([
            fs::canonicalize(&completed_path).unwrap(),
            fs::canonicalize(&running_a_path).unwrap(),
            fs::canonicalize(&running_z_path).unwrap(),
        ]);
        let update = fetch_active_thread_update_for_paths(
            &mut input,
            &receiver,
            &mut next_id,
            &root,
            &active_paths,
        );
        assert_eq!(
            update,
            ActiveThreadUpdate::Snapshot(vec![
                ActiveThread {
                    id: "running-z".into(),
                    created_at: Some(1),
                    updated_at: 20,
                    title: "title-running-z".into(),
                    model: "model-z".into(),
                    model_label: "model-z".into(),
                    total_tokens: Some(999),
                    context_usage_tokens: None,
                    context_window_tokens: None,
                    last_user_message_at: None,
                    is_subagent: false,
                    parent_thread_id: None,
                    depth: None,
                },
                ActiveThread {
                    id: "running-a".into(),
                    created_at: Some(1),
                    updated_at: 20,
                    title: "title-running-a".into(),
                    model: "model-a".into(),
                    model_label: "model-a".into(),
                    total_tokens: Some(111),
                    context_usage_tokens: None,
                    context_window_tokens: None,
                    last_user_message_at: None,
                    is_subagent: true,
                    parent_thread_id: Some("running-z".into()),
                    depth: Some(1),
                },
            ])
        );
        assert_eq!(next_id, 73);
        assert_eq!(String::from_utf8(input).unwrap().lines().count(), 3);

        let _ = fs::remove_dir_all(root);
    }

    fn write_distinct_running_rollout(
        path: &Path,
        model: &str,
        total_tokens: u64,
        context_usage_tokens: u64,
        context_window_tokens: u64,
        user_timestamp: &str,
        completed: bool,
    ) {
        let mut records = vec![
            json!({
                "type":"session_meta",
                "payload":{"id":path.file_stem().unwrap().to_str().unwrap()}
            }),
            json!({"type":"thread_context","model":model}),
            json!({
                "type":"event_msg",
                "timestamp":user_timestamp,
                "payload":{"type":"user_message"}
            }),
            json!({
                "type":"event_msg",
                "payload":{
                    "type":"token_count",
                    "info":{
                        "total_token_usage":{"total_tokens":total_tokens},
                        "last_token_usage":{"total_tokens":context_usage_tokens},
                        "model_context_window":context_window_tokens
                    }
                }
            }),
            json!({"type":"task_started"}),
        ];
        if completed {
            records.push(json!({"type":"task_complete"}));
        }
        fs::write(
            path,
            records
                .into_iter()
                .map(|value| value.to_string())
                .collect::<Vec<_>>()
                .join("\n")
                + "\n",
        )
        .unwrap();
    }

    #[test]
    fn session_traversal_bounds_count_and_depth_not_lifetime_file_size() {
        assert_eq!(super::security::MAX_SESSION_FILE_BYTES, 256 * 1024 * 1024);
        assert_eq!(
            super::security::MAX_SESSION_TOTAL_BYTES,
            2 * 1024 * 1024 * 1024
        );
        assert!(SessionTraversalBudget::default()
            .admit_file(1, 64 * 1024 * 1024 + 1)
            .is_ok());

        let mut files = SessionTraversalBudget::default();
        for _ in 0..super::security::MAX_SESSION_FILES {
            files.admit_file(1, 0).expect("file budget boundary");
        }
        assert!(files.admit_file(1, 0).is_err());

        assert!(SessionTraversalBudget::default()
            .admit_file(1, super::security::MAX_SESSION_FILE_BYTES + 1)
            .is_ok());
        assert!(SessionTraversalBudget::default()
            .admit_file(super::security::MAX_SESSION_DEPTH + 1, 0)
            .is_err());

        let root = std::env::temp_dir().join(format!(
            "codex-info-traversal-{}-{}",
            std::process::id(),
            Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        fs::create_dir(&root).unwrap();
        let safe = root.join("safe.jsonl");
        fs::write(&safe, "{}\n").unwrap();
        assert_eq!(session_jsonl_files(&root).unwrap(), vec![safe.clone()]);
        #[cfg(unix)]
        {
            use std::os::unix::fs::symlink;
            symlink("safe.jsonl", root.join("linked.jsonl")).unwrap();
            assert_eq!(session_jsonl_files(&root).unwrap(), vec![safe]);
        }
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn latest_session_selector_uses_whole_prefix_without_hole_filling() {
        let candidate = |name: &str, length: u64, modified_nanos: u128, inode: u64| {
            let path = PathBuf::from(format!("/sessions/{name}.jsonl"));
            SessionFileCandidate {
                fingerprint: LocalInputFileFingerprint {
                    path,
                    length,
                    modified_nanos,
                    #[cfg(unix)]
                    device: 10,
                    #[cfg(unix)]
                    inode,
                },
                recorded_source: super::usage_store::RecordedSessionSource {
                    root_identity: "unix:10:20".into(),
                    relative_path: format!("{name}.jsonl"),
                    file_bytes: length,
                    modified_nanos,
                    file_device: 10,
                    file_inode: inode,
                },
            }
        };
        let names = |files: &[SessionFileCandidate]| {
            files
                .iter()
                .map(|file| {
                    file.fingerprint
                        .path
                        .file_stem()
                        .unwrap()
                        .to_string_lossy()
                        .into_owned()
                })
                .collect::<Vec<_>>()
        };

        let (selected, overflow) = super::select_latest_session_prefix(
            vec![
                candidate("new", 6, 30, 1),
                candidate("middle", 4, 20, 2),
                candidate("old", 1, 10, 3),
            ],
            10,
        )
        .unwrap();
        assert_eq!(names(&selected), ["new", "middle"]);
        assert_eq!(names(&overflow), ["old"]);

        let (selected, overflow) = super::select_latest_session_prefix(
            vec![
                candidate("new", 6, 30, 1),
                candidate("middle", 5, 20, 2),
                candidate("old", 1, 10, 3),
            ],
            10,
        )
        .unwrap();
        assert_eq!(names(&selected), ["new"]);
        assert_eq!(names(&overflow), ["middle", "old"]);

        let (selected, overflow) = super::select_latest_session_prefix(
            vec![candidate("a", 1, 40, 4), candidate("z", 1, 40, 5)],
            2,
        )
        .unwrap();
        assert_eq!(names(&selected), ["z", "a"]);
        assert!(overflow.is_empty());

        let (selected, overflow) = super::select_latest_session_prefix(
            vec![candidate(
                "oversized",
                super::security::MAX_SESSION_FILE_BYTES + 1,
                50,
                6,
            )],
            u64::MAX,
        )
        .unwrap();
        assert_eq!(names(&selected), ["oversized"]);
        assert!(overflow.is_empty());
    }

    #[test]
    fn active_rollout_snapshot_accepts_append_and_defers_partial_tail() {
        let root = std::env::temp_dir().join(format!(
            "codex-info-rollout-append-{}-{}",
            std::process::id(),
            Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        fs::create_dir(&root).unwrap();
        let path = root.join("active.jsonl");
        let complete = concat!(
            "{\"type\":\"thread_context\",\"model\":\"gpt-5.6-sol\"}\n",
            "{\"type\":\"task_started\"}\n"
        );
        let partial = "{\"type\":\"event_msg\"";
        fs::write(&path, format!("{complete}{partial}")).unwrap();

        let before = fs::metadata(&path).unwrap();
        let mut file = File::open(&path).unwrap();
        let snapshot_len = file.metadata().unwrap().len();
        let complete_len = complete_rollout_prefix_len(&mut file, snapshot_len).unwrap();
        assert_eq!(complete_len, complete.len() as u64);
        file.seek(SeekFrom::Start(0)).unwrap();
        let rollout = {
            let mut reader = BufReader::new((&mut file).take(complete_len));
            thread_contract::parse_rollout_reader(&mut reader, complete_len).unwrap()
        };
        assert!(rollout.is_running());
        assert_eq!(rollout.model(), "gpt-5.6-sol");
        assert_eq!(rollout.total_tokens(), None);

        let remainder = concat!(
            ",\"payload\":{\"type\":\"token_count\",\"info\":{",
            "\"total_token_usage\":{\"total_tokens\":77}}}}\n"
        );
        let mut append = fs::OpenOptions::new().append(true).open(&path).unwrap();
        append.write_all(remainder.as_bytes()).unwrap();
        append.flush().unwrap();
        drop(append);
        let after = fs::metadata(&path).unwrap();
        assert!(same_rollout_identity(&before, &after));
        assert!(after.len() > before.len());

        let mut file = File::open(&path).unwrap();
        let complete_len = complete_rollout_prefix_len(&mut file, after.len()).unwrap();
        assert_eq!(complete_len, after.len());
        file.seek(SeekFrom::Start(0)).unwrap();
        let rollout = {
            let mut reader = BufReader::new((&mut file).take(complete_len));
            thread_contract::parse_rollout_reader(&mut reader, complete_len).unwrap()
        };
        assert!(rollout.is_running());
        assert_eq!(rollout.total_tokens(), Some(77));

        let other = root.join("other.jsonl");
        fs::write(&other, "{}\n").unwrap();
        assert!(!same_rollout_identity(
            &after,
            &fs::metadata(&other).unwrap()
        ));
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn thread_rollout_cache_tracks_observed_length_and_complete_offset() {
        let root = std::env::temp_dir().join(format!(
            "codex-info-thread-rollout-cache-{}-{}",
            std::process::id(),
            Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        fs::create_dir_all(&root).unwrap();
        let path = root.join("cached.jsonl");
        let initial = concat!(
            "{\"type\":\"session_meta\",\"payload\":{\"id\":\"cache-thread\"}}\n",
            "{\"type\":\"thread_context\",\"model\":\"gpt-5.6-sol\"}\n",
            "{\"type\":\"task_started\"}\n"
        );
        fs::write(&path, initial).unwrap();
        let canonical = fs::canonicalize(&path).unwrap();
        let mut cache = ThreadRolloutCache::default();

        let (thread_id, first) =
            read_active_thread_rollout_cached(&root, &path, &mut cache).unwrap();
        assert_eq!(thread_id, "cache-thread");
        assert!(first.is_running());
        let initial_len = initial.len() as u64;
        let entry = cache.entries.get(&canonical).expect("initial cache entry");
        assert_eq!(entry.observed_len, initial_len);
        assert_eq!(entry.complete_offset, initial_len);
        assert_eq!(entry.snapshot, first);

        let (_, unchanged) = read_active_thread_rollout_cached(&root, &path, &mut cache).unwrap();
        assert_eq!(unchanged, first);
        let entry = cache
            .entries
            .get(&canonical)
            .expect("unchanged cache entry");
        assert_eq!(entry.observed_len, initial_len);
        assert_eq!(entry.complete_offset, initial_len);

        let partial = "{\"type\":\"event_msg\"";
        let mut append = fs::OpenOptions::new().append(true).open(&path).unwrap();
        append.write_all(partial.as_bytes()).unwrap();
        drop(append);
        let partial_len = fs::metadata(&path).unwrap().len();
        let (_, partial_snapshot) =
            read_active_thread_rollout_cached(&root, &path, &mut cache).unwrap();
        assert_eq!(partial_snapshot, first);
        let entry = cache.entries.get(&canonical).expect("partial cache entry");
        assert_eq!(entry.observed_len, partial_len);
        assert_eq!(entry.complete_offset, initial_len);

        let remainder = concat!(
            ",\"payload\":{\"type\":\"token_count\",\"info\":{",
            "\"total_token_usage\":{\"total_tokens\":77}}}}\n"
        );
        let mut append = fs::OpenOptions::new().append(true).open(&path).unwrap();
        append.write_all(remainder.as_bytes()).unwrap();
        drop(append);
        let completed_len = fs::metadata(&path).unwrap().len();
        let (_, completed) = read_active_thread_rollout_cached(&root, &path, &mut cache).unwrap();
        assert_eq!(completed.total_tokens(), Some(77));
        let entry = cache
            .entries
            .get(&canonical)
            .expect("completed cache entry");
        assert_eq!(entry.observed_len, completed_len);
        assert_eq!(entry.complete_offset, completed_len);

        let (_, stable) = read_active_thread_rollout_cached(&root, &path, &mut cache).unwrap();
        assert_eq!(stable, completed);
        let entry = cache.entries.get(&canonical).expect("stable cache entry");
        assert_eq!(entry.observed_len, completed_len);
        assert_eq!(entry.complete_offset, completed_len);

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn seeded_rollout_cache_miss_reads_only_checkpoint_tail() {
        let root = std::env::temp_dir().join(format!(
            "codex-info-thread-rollout-seeded-{}-{}",
            std::process::id(),
            Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        fs::create_dir_all(&root).unwrap();
        let path = root.join("seeded.jsonl");
        let prefix = concat!(
            "{\"type\":\"session_meta\",\"payload\":{\"id\":\"seeded-thread\"}}\n",
            "{\"type\":\"thread_context\",\"model\":\"wrong-prefix-model\"}\n"
        );
        fs::write(&path, prefix).unwrap();
        fs::OpenOptions::new()
            .write(true)
            .open(&path)
            .unwrap()
            .set_len(security::MAX_SESSION_FILE_BYTES + 1)
            .unwrap();
        let tail = "{\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"total_tokens\":123}}}}\n";
        let checkpoint_metadata = fs::metadata(&path).unwrap();
        #[cfg(unix)]
        let (file_device, file_inode) = {
            use std::os::unix::fs::MetadataExt;
            (checkpoint_metadata.dev(), checkpoint_metadata.ino())
        };
        #[cfg(not(unix))]
        let (file_device, file_inode) = (0, 0);
        let root_metadata = fs::symlink_metadata(&root).unwrap();
        let mut checkpoint = super::usage_store::SessionCheckpoint {
            previous_cache_write_input: None,
            root_identity: super::session_root_identity(&root, &root_metadata).unwrap(),
            relative_path: "seeded.jsonl".into(),
            file_device,
            file_inode,
            committed_offset: security::MAX_SESSION_FILE_BYTES + 1,
            discard_until_lf: false,
            collector_epoch: 1,
            cycle_seq: 1,
            prefix_generation: 1,
            prefix_sha256: "11".repeat(32),
            fully_attributed_from_zero: true,
            token_baseline_known: true,
            last_task_running: Some(true),
            last_model: Some("SOL".into()),
            previous_total: 100,
            previous_input: 80,
            previous_cached_input: 20,
            previous_output: 20,
        };
        let mut append = fs::OpenOptions::new().append(true).open(&path).unwrap();
        append.write_all(tail.as_bytes()).unwrap();
        drop(append);

        let mut cache = ThreadRolloutCache::default();
        let (thread_id, rollout) = super::read_active_thread_rollout_cached_with_checkpoints(
            &root,
            &path,
            &mut cache,
            std::slice::from_ref(&checkpoint),
        )
        .expect("durable checkpoint seeds the parser without replaying the prefix");
        assert_eq!(thread_id, "seeded-thread");
        assert!(rollout.is_running());
        assert_eq!(rollout.model(), "SOL");
        assert_eq!(rollout.total_tokens(), Some(123));
        assert_eq!(
            cache
                .entries
                .get(&fs::canonicalize(&path).unwrap())
                .unwrap()
                .complete_offset,
            fs::metadata(&path).unwrap().len()
        );
        checkpoint.last_task_running = None;
        let (_, legacy_rollout) = super::read_active_thread_rollout_cached_with_checkpoints(
            &root,
            &path,
            &mut ThreadRolloutCache::default(),
            std::slice::from_ref(&checkpoint),
        )
        .expect("legacy checkpoint bridges a verified appended turn");
        assert!(legacy_rollout.is_running());
        let _ = fs::remove_dir_all(root);
    }

