    #[test]
    fn production_rollout_reader_separates_record_recovery_from_candidate_failure() {
        let root = std::env::temp_dir().join(format!(
            "codex-info-rollout-boundaries-{}-{}",
            std::process::id(),
            Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        fs::create_dir(&root).unwrap();

        let recoverable = root.join("recoverable.jsonl");
        let prefix = concat!(
            "{\"type\":\"thread_context\",\"model\":\"gpt-5.6-sol\"}\n",
            "{\"type\":\"task_started\"}\n"
        );
        let oversized = format!(
            "{{\"type\":\"response_item\",\"payload\":\"{}\"}}\n",
            "x".repeat(security::MAX_JSONL_LINE_BYTES + 128)
        );
        let suffix = concat!(
            "{\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",",
            "\"info\":{\"total_token_usage\":{\"total_tokens\":321}}}}\n"
        );
        let mut bytes = prefix.as_bytes().to_vec();
        bytes.extend_from_slice(oversized.as_bytes());
        bytes.extend_from_slice(&[b'{', 0xff, b'}', b'\n']);
        bytes.extend_from_slice(suffix.as_bytes());
        fs::write(&recoverable, bytes).unwrap();
        let rollout = read_thread_rollout_path(&root, &recoverable)
            .expect("oversized/invalid-UTF8 records are isolated by the production reader");
        assert!(rollout.is_running());
        assert_eq!(rollout.total_tokens(), Some(321));

        let malformed = root.join("malformed.jsonl");
        fs::write(
            &malformed,
            concat!(
                "{\"type\":\"thread_context\",\"model\":\"gpt-5.6-sol\"}\n",
                "{not-json}\n",
                "{\"type\":\"task_started\"}\n"
            ),
        )
        .unwrap();
        assert!(read_thread_rollout_path(&root, &malformed).is_err());

        let known_event_error = root.join("known-event-error.jsonl");
        fs::write(
            &known_event_error,
            concat!(
                "{\"type\":\"thread_context\",\"model\":\"gpt-5.6-sol\"}\n",
                "{\"type\":\"event_msg\",\"payload\":{}}\n"
            ),
        )
        .unwrap();
        assert!(read_thread_rollout_path(&root, &known_event_error).is_err());

        #[cfg(unix)]
        {
            std::os::unix::fs::symlink(&malformed, root.join("symlink.jsonl")).unwrap();
            assert!(read_thread_rollout_path(&root, &root.join("symlink.jsonl")).is_err());
        }
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn rpc_request_enforces_mismatch_timeout_and_error_redaction() {
        let (tx, rx) = mpsc::channel();
        for _ in 0..super::security::MAX_RPC_IGNORED_MESSAGES {
            tx.send(RpcReadEvent::Line(
                super::security::RpcLine::new(r#"{"jsonrpc":"2.0","id":2,"result":{}}"#).unwrap(),
            ))
            .unwrap();
        }
        tx.send(RpcReadEvent::Line(
            super::security::RpcLine::new(r#"{"jsonrpc":"2.0","id":1,"result":{"ok":true}}"#)
                .unwrap(),
        ))
        .unwrap();
        let mut input = Vec::new();
        assert_eq!(
            request_with_timeout(
                &mut input,
                &rx,
                1,
                "test/read",
                Value::Null,
                Duration::from_millis(50),
            )
            .unwrap(),
            json!({"ok":true})
        );

        let (tx, rx) = mpsc::channel();
        for _ in 0..=super::security::MAX_RPC_IGNORED_MESSAGES {
            tx.send(RpcReadEvent::Line(
                super::security::RpcLine::new(r#"{"jsonrpc":"2.0","id":2,"result":{}}"#).unwrap(),
            ))
            .unwrap();
        }
        assert!(request_with_timeout(
            &mut Vec::new(),
            &rx,
            1,
            "test/read",
            Value::Null,
            Duration::from_millis(50),
        )
        .unwrap_err()
        .contains("上限"));

        let (_tx, rx) = mpsc::channel();
        assert!(request_with_timeout(
            &mut Vec::new(),
            &rx,
            1,
            "test/read",
            Value::Null,
            Duration::from_millis(1),
        )
        .unwrap_err()
        .contains("タイムアウト"));

        let (tx, rx) = mpsc::channel();
        tx.send(RpcReadEvent::Line(
            super::security::RpcLine::new(
                r#"{"jsonrpc":"2.0","id":1,"error":{"secret":"token-value"}}"#,
            )
            .unwrap(),
        ))
        .unwrap();
        let error = request_with_timeout(
            &mut Vec::new(),
            &rx,
            1,
            "test/read",
            Value::Null,
            Duration::from_millis(50),
        )
        .unwrap_err();
        assert!(!error.contains("token-value"));
    }

    #[test]
    fn account_update_generation_is_local_strict_and_permanently_invalidated() {
        let valid_raw = r#"{"jsonrpc":"2.0","method":"account/updated","params":{"authMode":"chatgpt","planType":"pro"}}"#;
        let valid: Value = serde_json::from_str(valid_raw).unwrap();
        let mut tracker = super::AccountUpdateTracker::default();
        assert!(tracker.observe(&valid, valid_raw).unwrap());
        assert_eq!(tracker.generation, 1);

        let ordinary_raw = r#"{"jsonrpc":"2.0","id":1,"result":{}}"#;
        let ordinary: Value = serde_json::from_str(ordinary_raw).unwrap();
        assert!(!tracker.observe(&ordinary, ordinary_raw).unwrap());
        assert_eq!(tracker.generation, 1);

        let malformed_raw =
            r#"{"jsonrpc":"2.0","method":"account/updated","params":{},"extra":true}"#;
        let malformed: Value = serde_json::from_str(malformed_raw).unwrap();
        assert!(tracker.observe(&malformed, malformed_raw).is_err());
        assert!(!tracker.valid);
        assert!(tracker.observe(&valid, valid_raw).is_err());
        assert_eq!(tracker.generation, 1);

        let hidden_raw = r#"{"method":"account/updated","method":"ordinary/event","params":{}}"#;
        let hidden: Value = serde_json::from_str(hidden_raw).unwrap();
        let mut hidden_tracker = super::AccountUpdateTracker::default();
        assert!(hidden_tracker.observe(&hidden, hidden_raw).is_err());
        assert!(!hidden_tracker.valid);

        let mut overflow = super::AccountUpdateTracker {
            generation: u64::MAX,
            valid: true,
        };
        assert!(overflow.observe(&valid, valid_raw).is_err());
        assert!(!overflow.valid);
    }

