    #[test]
    fn same_timestamp_reset_drift_with_conflicting_quota_omits_only_that_minute() {
        let reset_at = 2_000_000_i64;
        let history = UsageHistory {
            samples: vec![
                UsageHistorySample::new(
                    960_000,
                    reset_at,
                    97.0,
                    ModelDollarTotals {
                        luna: 7.6,
                        ..ModelDollarTotals::default()
                    },
                ),
                // This mirrors the live history's 12-second reset drift: both
                // rows have model usage, but they cannot be ordered into a
                // fabricated 97% -> 98% quota transition.
                UsageHistorySample::new(
                    960_000,
                    reset_at + 12,
                    98.0,
                    ModelDollarTotals {
                        luna: 7.6,
                        ..ModelDollarTotals::default()
                    },
                ),
            ],
            ..UsageHistory::default()
        };

        let selected = history.samples_for_reset(Some(reset_at));
        assert!(selected.is_empty());
        assert_eq!(
            canonicalize_public_history_samples(&history.samples).unwrap(),
            Vec::<UsageHistorySample>::new()
        );
    }

    #[test]
    fn exact_key_noncomparable_observations_never_form_a_synthetic_vector() {
        let mut history = UsageHistory::default();
        let timestamp = 1_788_040_140;
        let reset_at = 1_788_644_929;
        let first = UsageHistorySample {
            timestamp,
            reset_at,
            remaining_percent: 41.0,
            sol_dollars: 9.0,
            terra_dollars: 1.0,
            luna_dollars: 0.0,
            sol_tokens: 90,
            terra_tokens: 10,
            luna_tokens: 0,
        };
        let second = UsageHistorySample {
            sol_dollars: 8.0,
            terra_dollars: 2.0,
            sol_tokens: 80,
            terra_tokens: 20,
            ..first.clone()
        };

        history.record(first.clone());
        history.record(second.clone());

        assert_eq!(history.samples, [first, second]);
        assert_eq!(
            canonicalize_public_history_samples(&history.samples).unwrap(),
            Vec::<UsageHistorySample>::new()
        );
        assert!(history.samples_for_reset(Some(reset_at)).is_empty());
    }

    #[test]
    fn startup_load_sanitizes_legacy_same_timestamp_quota_collision() {
        let db_path = test_history_path("startup-same-timestamp-collision");
        let timestamp = 1_999_999_940;
        let rows = [
            UsageHistorySample {
                timestamp,
                reset_at: 2_000_000_500,
                remaining_percent: 88.0,
                sol_dollars: 1.0,
                terra_dollars: 0.0,
                luna_dollars: 0.0,
                sol_tokens: 0,
                terra_tokens: 0,
                luna_tokens: 0,
            },
            UsageHistorySample {
                timestamp,
                reset_at: 2_000_000_530,
                remaining_percent: 14.0,
                sol_dollars: 0.0,
                terra_dollars: 0.0,
                luna_dollars: 0.0,
                sol_tokens: 0,
                terra_tokens: 0,
                luna_tokens: 0,
            },
        ];
        let mut store = UsageStore::open(&db_path).unwrap();
        store
            .upsert_samples(
                &rows
                    .iter()
                    .map(UsageHistorySample::to_store)
                    .collect::<Vec<_>>(),
            )
            .unwrap();
        drop(store);

        let now = Utc.timestamp_opt(2_000_001_000, 0).single().unwrap();
        let history = UsageHistory::load_from_db_path_at(Some(db_path.clone()), now);
        assert_eq!(
            history
                .samples
                .iter()
                .filter(|sample| sample.timestamp == timestamp)
                .count(),
            2
        );
        assert!(history
            .samples
            .iter()
            .filter(|sample| sample.timestamp == timestamp)
            .any(|sample| (sample.remaining_percent - 88.0).abs() < f64::EPSILON));
        assert!(history
            .samples
            .iter()
            .filter(|sample| sample.timestamp == timestamp)
            .any(|sample| (sample.remaining_percent - 14.0).abs() < f64::EPSILON));
        assert_eq!(
            canonicalize_public_history_samples(&history.samples).unwrap(),
            Vec::<UsageHistorySample>::new()
        );
        let _ = fs::remove_dir_all(db_path.parent().unwrap());
    }

    #[test]
    fn startup_maintenance_prunes_before_the_calendar_cutoff_only_once() {
        let db_path = test_history_path("startup-maintenance");
        let now = Utc.with_ymd_and_hms(2024, 5, 31, 12, 34, 56).unwrap();
        let cutoff = three_months_before_utc(now);
        let samples = [
            UsageHistorySample {
                timestamp: cutoff - 1,
                reset_at: cutoff + 10_000,
                remaining_percent: 80.0,
                sol_dollars: 1.0,
                terra_dollars: 0.0,
                luna_dollars: 0.0,
                sol_tokens: 0,
                terra_tokens: 0,
                luna_tokens: 0,
            },
            UsageHistorySample {
                timestamp: cutoff,
                reset_at: cutoff + 20_000,
                remaining_percent: 70.0,
                sol_dollars: 2.0,
                terra_dollars: 0.0,
                luna_dollars: 0.0,
                sol_tokens: 0,
                terra_tokens: 0,
                luna_tokens: 0,
            },
        ];
        let mut store = UsageStore::open(&db_path).unwrap();
        store
            .upsert_samples(
                &samples
                    .iter()
                    .map(UsageHistorySample::to_store)
                    .collect::<Vec<_>>(),
            )
            .unwrap();
        drop(store);

        daemon::maintain_history_database_for_test(&db_path, now).unwrap();
        let mut history = UsageHistory::load_from_db_path_at(Some(db_path.clone()), now);
        history.startup_maintenance(now);

        assert_eq!(
            history
                .samples
                .iter()
                .map(|sample| sample.timestamp)
                .collect::<Vec<_>>(),
            Vec::<i64>::new()
        );
        let persisted = UsageStore::open(&db_path).unwrap().load_all().unwrap();
        assert_eq!(persisted.len(), 1);
        assert_eq!(persisted[0].timestamp, cutoff);

        history.samples.push(samples[0].clone());
        history.startup_maintenance(now);
        assert!(history
            .samples
            .iter()
            .any(|sample| sample.timestamp == cutoff - 1));
        let _ = fs::remove_dir_all(db_path.parent().unwrap());
    }

