    fn write_recovery_ledger(name: &str, rows: &[serde_json::Value]) -> PathBuf {
        let path = std::env::temp_dir().join(format!(
            "codex-info-recovery-{name}-{}-{}.jsonl",
            std::process::id(),
            rows.len()
        ));
        let contents = rows
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join("\n")
            + "\n";
        fs::write(&path, contents).unwrap();
        path
    }

