    #[test]
    fn token_graph_marks_legacy_zero_rows_unavailable_until_vector_recovery() {
        let samples = [
            UsageHistorySample::new_with_usage(
                100,
                1_000,
                95.0,
                ModelDollarTotals {
                    sol: 1.0,
                    terra: 2.0,
                    luna: 3.0,
                },
                ModelTokenTotals {
                    sol: 1_000,
                    terra: 2_000,
                    luna: 3_000,
                },
            ),
            // This is the shape of a legacy row: dollars are present, but
            // token columns were not available yet. It must not reset the
            // cumulative counters or turn the next observation into a delta.
            UsageHistorySample::new(
                160,
                1_000,
                94.0,
                ModelDollarTotals {
                    sol: 1.5,
                    terra: 2.5,
                    luna: 3.5,
                },
            ),
            UsageHistorySample::new_with_usage(
                220,
                1_000,
                93.0,
                ModelDollarTotals {
                    sol: 2.0,
                    terra: 3.0,
                    luna: 4.0,
                },
                ModelTokenTotals {
                    sol: 2_000,
                    terra: 4_000,
                    luna: 8_000,
                },
            ),
            // A later legacy row must not erase the latest known endpoint.
            UsageHistorySample::new(
                280,
                1_000,
                92.0,
                ModelDollarTotals {
                    sol: 2.5,
                    terra: 3.5,
                    luna: 4.5,
                },
            ),
        ];
        let references = samples.iter().collect::<Vec<_>>();
        let points = minute_model_spend_for_metric(&references, true);
        assert_eq!(points.len(), 4);
        assert_eq!(
            (points[0].sol, points[0].terra, points[0].luna),
            (1_000.0, 2_000.0, 3_000.0)
        );
        assert!(!model_spend_is_reliable(&points[1]));
        assert_eq!(
            (points[2].sol, points[2].terra, points[2].luna),
            (2_000.0, 4_000.0, 8_000.0)
        );
        assert!(!model_spend_is_reliable(&points[3]));

        let graph = graph_paths_for_selection(&references, 0, 300, true, true, true, true);
        assert!(graph.current_luna_label.is_empty());
        assert!(graph.current_terra_label.is_empty());
        assert!(graph.current_sol_label.is_empty());
        assert!(graph.sol_flat.matches('M').count() > 2);
    }

